SET search_path = public, extensions;

-- Extended concept: Variation
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Differences among the members of a set, such as organisms, practices, designs or candidate solutions. These differences give selection and chance something to act on. Variation matters for change over time only when some of it is passed on.","excludes":"Variation builds up only if it is passed on, by genes in biology and by learning or copying elsewhere. A tan is not inherited. Cultural and computing variants can be made on purpose, while mutation ignores need. Diversity of kinds, such as many species, is a different idea.","core_counterparts":[{"space":"bio","label":"Mutation","relation":"related"},{"space":"bio","label":"Allele","relation":"related"},{"space":"bio","label":"Heritable Variation","relation":"broader"}],"curriculum_use":"Grade 5-6 Vielfalt topics, grade 10 Genetik and Entstehung der Artenvielfalt (Mutation, Rekombination), and any topic about differences among designs, styles or candidate solutions.","grounding":["OE-CONCEPT-oe-interdisciplinary-variation","OE-CONCEPT-bio-core-mutation","OE-CONCEPT-bio-core-allele","doi:10.1146/annurev.es.01.110170.000245 (Lewontin 1970, The units of selection; Crossref-checked)","doi:10.1016/j.jaa.2005.08.001 (Eerkens & Lipo 2005; Crossref-checked)","doi:10.1098/rspb.2004.2746 (Bentley, Hahn & Shennan 2004; Crossref-checked)","ISBN 9780262631853 (Mitchell, An Introduction to Genetic Algorithms; Open Library-checked)","ISBN 9780521296816 (Basalla 1988, The Evolution of Technology; Open Library-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7601-1 (Biologie grade 10, Entstehung der Artenvielfalt; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Allele","core_counterparts":[{"space":"bio","label":"Allele","relation":"related"}],"reason":"Alleles are one unit of biological variation. Variation already says differences among members, so a biology facet there covers alleles.","confidence":"medium"},{"core_concept":"Heritable Variation","core_counterparts":[{"space":"bio","label":"Heritable Variation","relation":"broader"}],"reason":"Variation plus the condition that differences are passed on. That condition links Variation to Inheritance and is better stated inside Variation than as a second concept.","confidence":"medium"}]}'::jsonb) WHERE id = '877daea8-799c-5c43-920a-b7d3fc131c80';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('790eeb60-c358-529c-bfa2-79c49db46127', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Variation (biology)', 'Individuals of a species differ in the versions of genes they carry (alleles) and in the traits these help produce. New versions arise by mutation, and recombination shuffles existing ones. Only differences that parents pass on count toward evolution.', '877daea8-799c-5c43-920a-b7d3fc131c80', '{"level":"discipline-facet","facet_of":"Variation","definition":"Individuals of a species differ in the versions of genes they carry (alleles) and in the traits these help produce. New versions arise by mutation, and recombination shuffles existing ones. Only differences that parents pass on count toward evolution.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-variation-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e1ef22a2-728d-5623-b5a7-816ebab0c8e7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Variation (culture)', 'People differ in the words, skills and beliefs they hold. Differences arise from invention and from copying errors, and only those that others learn can spread. Pottery styles and first names are tracked this way.', '877daea8-799c-5c43-920a-b7d3fc131c80', '{"level":"discipline-facet","facet_of":"Variation","definition":"People differ in the words, skills and beliefs they hold. Differences arise from invention and from copying errors, and only those that others learn can spread. Pottery styles and first names are tracked this way.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-variation-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ba958dc3-2341-5f50-b601-27ca7b6dba05', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Variation (technology)', 'Versions of a tool, machine or program differ in materials, shape and code. They arise from deliberate changes and from imperfect copying of an earlier design. Only versions that are built or recorded can be copied later.', '877daea8-799c-5c43-920a-b7d3fc131c80', '{"level":"discipline-facet","facet_of":"Variation","definition":"Versions of a tool, machine or program differ in materials, shape and code. They arise from deliberate changes and from imperfect copying of an earlier design. Only versions that are built or recorded can be copied later.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-variation-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4e136449-42c6-5a09-ba9c-b37ea672e7ab', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Variation (AI and computation)', 'The candidates in an evolutionary algorithm differ in their encoded contents. Random mutation and crossover (mixing two parents) create new differences. If the pool loses its variety, the search stalls.', '877daea8-799c-5c43-920a-b7d3fc131c80', '{"level":"discipline-facet","facet_of":"Variation","definition":"The candidates in an evolutionary algorithm differ in their encoded contents. Random mutation and crossover (mixing two parents) create new differences. If the pool loses its variety, the search stalls.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-variation-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Evolutionary Process
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Change in the make-up of a population of variants over repeated rounds of copying or reproduction. Variants arise, are passed on, and differ in how often they are kept, by selection and by chance. Rounds are generations, turns of social learning or algorithm cycles.","excludes":"One growing organism or one tuned program is not a population evolving. Biological variants arise without regard to need, and evolution has no target. An evolutionary algorithm has one, set by its programmer. Trial and error in one person as selection (Skinner, Campbell) is contested and left out.","core_counterparts":[{"space":"bio","label":"Natural Selection","relation":"related"},{"space":"bio","label":"Drift","relation":"broader"},{"space":"bio","label":"Change in Populations","relation":"broader"},{"space":"soc","label":"Social Change","relation":"related"},{"space":"comp","label":"Search","relation":"related"}],"curriculum_use":"Grade 10 Biologie ''Entstehung der Artenvielfalt'', the hint ''biologische und kulturelle Evolution'' under Stammesgeschichte des Menschen, and any topic on change in technology or language over time.","grounding":["OE-CONCEPT-oe-interdisciplinary-evolutionary-process","OE-CONCEPT-bio-core-evolution","OE-PROPOSITION-blind-variation-selection-by-consequences","doi:10.1146/annurev.es.01.110170.000245 (Lewontin 1970, The units of selection; Crossref-checked)","doi:10.1017/S0140525X06009083 (Mesoudi, Whiten & Laland 2006; Crossref-checked)","doi:10.1037/h0040373 (Campbell 1960; Crossref-checked)","doi:10.1126/science.7244649 (Skinner 1981; Crossref-checked)","doi:10.1038/nature14544 (Eiben & Smith 2015; Crossref-checked)","ISBN 9780226520438 (Mesoudi 2011, Cultural Evolution; Open Library-checked)","ISBN 9780226069333 (Boyd & Richerson, Culture and the Evolutionary Process; Open Library-checked)","ISBN 9780521296816 (Basalla 1988, The Evolution of Technology; Open Library-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7601-1 (Biologie grade 10, Entstehung der Artenvielfalt; read in the topic cache)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7602-1 (Biologie grade 10, Stammesgeschichte des Menschen; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '212e3ab0-5575-572b-89fe-cff0ab90594d';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('038e35f4-09eb-5239-9784-c31cb610df00', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Evolutionary Process (biology)', 'Populations of organisms change across generations in the heritable traits they carry. Mutation and recombination supply variants. Selection, chance and isolation change which variants are common.', '212e3ab0-5575-572b-89fe-cff0ab90594d', '{"level":"discipline-facet","facet_of":"Evolutionary Process","definition":"Populations of organisms change across generations in the heritable traits they carry. Mutation and recombination supply variants. Selection, chance and isolation change which variants are common.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-evolutionary-process-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8d2b6402-5a7a-5874-8883-24cacd62c21d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Evolutionary Process (culture)', 'Practices, words and designs held by a community change as people learn from one another. Invention and copying errors supply variants. Biased adoption, chance and group size change which variants are common.', '212e3ab0-5575-572b-89fe-cff0ab90594d', '{"level":"discipline-facet","facet_of":"Evolutionary Process","definition":"Practices, words and designs held by a community change as people learn from one another. Invention and copying errors supply variants. Biased adoption, chance and group size change which variants are common.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-evolutionary-process-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1010aed2-97de-5749-9d88-3ceaf877ca31', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Evolutionary Process (technology)', 'Designs change across successive versions. Makers vary a design, buyers and testers favor some versions, and later makers copy those. Parts can also be borrowed from unrelated designs.', '212e3ab0-5575-572b-89fe-cff0ab90594d', '{"level":"discipline-facet","facet_of":"Evolutionary Process","definition":"Designs change across successive versions. Makers vary a design, buyers and testers favor some versions, and later makers copy those. Parts can also be borrowed from unrelated designs.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-evolutionary-process-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d0b4fe0f-0549-5976-a953-52cb05509498', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Evolutionary Process (AI and computation)', 'An evolutionary algorithm keeps a pool of candidate solutions. Each round it varies candidates, scores them and copies higher scorers into the next round. The programmer sets the pool, the scoring rule and the number of rounds.', '212e3ab0-5575-572b-89fe-cff0ab90594d', '{"level":"discipline-facet","facet_of":"Evolutionary Process","definition":"An evolutionary algorithm keeps a pool of candidate solutions. Each round it varies candidates, scores them and copies higher scorers into the next round. The programmer sets the pool, the scoring rule and the number of rounds.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-evolutionary-process-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Niche Construction
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Organisms or groups change their surroundings, and the changes alter the conditions that later members of their own or other populations face. The changes often outlast the individuals who made them. They may be accidental or planned.","excludes":"Intent is optional: dams and earthworm soil are unplanned, while farming is often planned. A change counts only if it alters later conditions for the maker or others. Footprints that the next tide erases do not. It changes what selection acts on and carries no plan for evolving.","core_counterparts":[{"space":"bio","label":"Selection Pressure","relation":"related"}],"curriculum_use":"Grade 10 Biologie hints under Stammesgeschichte des Menschen (Feuergebrauch, Nahrungszubereitung, Übergang von Jagd zu Feldbau), grade 9 Zusammenhänge im Ökosystem, and Haustiere.","grounding":["OE-CONCEPT-oe-interdisciplinary-niche-construction","OE-DESIGNPRINCIPLE-behaviorally-mediated-selection-first-class","doi:10.1017/S0140525X00002417 (Laland, Odling-Smee & Feldman 2000; Crossref-checked)","doi:10.1098/rspb.2015.1019 (Laland et al. 2015; Crossref-checked)","doi:10.1038/nrg2734 (Laland, Odling-Smee & Myles 2010; Crossref-checked)","doi:10.1098/rstb.2010.0253 (Smith 2011; Crossref-checked)","ISBN 9780691044378 (Odling-Smee, Laland & Feldman 2003; Open Library-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7602-1 (Biologie grade 10, Stammesgeschichte des Menschen; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '3756d347-25a4-5484-bac4-2a3a061f6def';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('16467bce-0f7c-5e76-a755-7a6adac6a357', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Niche Construction (biology)', 'Beavers build dams, earthworms change soil and termites build mounds. The changes last, so descendants and neighbors face altered conditions and different traits may do well. No plan is needed.', '3756d347-25a4-5484-bac4-2a3a061f6def', '{"level":"discipline-facet","facet_of":"Niche Construction","definition":"Beavers build dams, earthworms change soil and termites build mounds. The changes last, so descendants and neighbors face altered conditions and different traits may do well. No plan is needed.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-niche-construction-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b73678e5-8de1-5109-997c-1eecd76ed5eb', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Niche Construction (culture)', 'Farming, herding, building and fire use change landscapes, diets and disease. Later generations inherit the altered conditions together with the knowledge. Dairy farming raised the advantage of genes that let adults digest milk sugar.', '3756d347-25a4-5484-bac4-2a3a061f6def', '{"level":"discipline-facet","facet_of":"Niche Construction","definition":"Farming, herding, building and fire use change landscapes, diets and disease. Later generations inherit the altered conditions together with the knowledge. Dairy farming raised the advantage of genes that let adults digest milk sugar.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-niche-construction-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Domestication
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"A long-running two-way relationship in which people shape another species'' breeding and that species shapes human food, work and settlement. It is a case of niche construction and coevolution.","excludes":"Domestication goes beyond selective breeding, because the relationship runs both ways. Early stages were often unplanned. Taming one animal changes its behavior within one lifetime and is not inherited. Claims about self-domestication of humans or other species are contested and left out.","core_counterparts":[{"space":"bio","label":"Domestication","relation":"shifted"},{"space":"bio","label":"Selection Pressure","relation":"related"}],"curriculum_use":"Grade 10 Biologie Genetik (klassische Züchtungsmethoden), grade 5 Biologie Vögel als Haustiere, and the hint Übergang von Jagd zu Feldbau under Stammesgeschichte des Menschen.","grounding":["OE-CONCEPT-bio-core-natural-selection","doi:10.1073/pnas.1501711112 (Zeder 2015; Crossref-checked)","doi:10.1146/annurev-ecolsys-110512-135813 (Larson & Fuller 2014; Crossref-checked)","doi:10.1038/nrg2734 (Laland, Odling-Smee & Myles 2010; Crossref-checked)","doi:10.1098/rstb.2010.0253 (Smith 2011; Crossref-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7602-1 (Biologie grade 10, Stammesgeschichte des Menschen; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '95f07717-21d3-573b-a081-9c8855a489ae';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('be6a43ab-c052-5752-8d35-a203815f3b31', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Domestication (biology)', 'People choose which plants or animals breed and supply food and shelter. Over generations the kept population shifts, as in tamer animals or seed-holding plants. Some selection is deliberate and some is an unplanned effect of life with people.', '95f07717-21d3-573b-a081-9c8855a489ae', '{"level":"discipline-facet","facet_of":"Domestication","definition":"People choose which plants or animals breed and supply food and shelter. Over generations the kept population shifts, as in tamer animals or seed-holding plants. Some selection is deliberate and some is an unplanned effect of life with people.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-domestication-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1ce017d4-3595-573b-8881-78a5b056dd8d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Domestication (culture)', 'Keeping crops and herds changes human life: diets, work, villages and trade. Dairying favored adults who digest milk sugar. Knowledge of breeding and care is passed on as practice and as tradition.', '95f07717-21d3-573b-a081-9c8855a489ae', '{"level":"discipline-facet","facet_of":"Domestication","definition":"Keeping crops and herds changes human life: diets, work, villages and trade. Dairying favored adults who digest milk sugar. Knowledge of breeding and care is passed on as practice and as tradition.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-domestication-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Innovation
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"A new variant appears in a system that did not hold it before. It may arise by chance, by copying error, by recombining old parts or by deliberate effort. Whether it spreads is a separate question.","excludes":"Biological mutation ignores need, while human invention is often aimed at a goal. Chance may play a part in both. A new variant changes a population only after it is copied. Innovation does not imply improvement. Most mutations change nothing or do harm, and many inventions fail.","core_counterparts":[{"space":"bio","label":"Mutation","relation":"broader"}],"curriculum_use":"Grade 9-10 Biologie topics on Mutation and Rekombination, topics on inventions in Technik and Geschichte, and any topic on how solutions are generated.","grounding":["OE-CONCEPT-oe-interdisciplinary-innovation","OE-CONCEPT-bio-core-mutation","ISBN 9780198526223 (Reader & Laland 2003, Animal Innovation; Open Library-checked)","ISBN 9781416544050 (Arthur 2009, The Nature of Technology; Open Library-checked)","ISBN 9780521296816 (Basalla 1988, The Evolution of Technology; Open Library-checked)","doi:10.1016/j.jaa.2005.08.001 (Eerkens & Lipo 2005; Crossref-checked)","doi:10.1162/EVCO_a_00025 (Lehman & Stanley 2011; Crossref-checked)","ISBN 9780262631853 (Mitchell, An Introduction to Genetic Algorithms; Open Library-checked)","ISBN 9780226520438 (Mesoudi 2011, Cultural Evolution; Open Library-checked)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Mutation","core_counterparts":[{"space":"bio","label":"Mutation","relation":"broader"}],"reason":"Mutation is the biology case of generating a new variant, which Innovation names. The crosswalk already treated Innovation as broader.","confidence":"medium"}]}'::jsonb) WHERE id = '183d2755-1489-554c-9b9e-e2cc8792592e';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('06bf1ace-6043-5129-970a-7b9974c87f35', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Innovation (biology)', 'A new heritable variant arises as a change in DNA (mutation) or as a new combination of existing DNA (recombination). Mutations arise without regard to whether they would help.', '183d2755-1489-554c-9b9e-e2cc8792592e', '{"level":"discipline-facet","facet_of":"Innovation","definition":"A new heritable variant arises as a change in DNA (mutation) or as a new combination of existing DNA (recombination). Mutations arise without regard to whether they would help.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-innovation-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('39a42d27-cf9c-5d29-9a1a-f2bc72e69955', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Innovation (cognition)', 'An individual finds a new solution to a problem, usually by trial and error and sometimes by apparent insight. Animals do this in many species, for example when they exploit a new food source. It can aim at a goal.', '183d2755-1489-554c-9b9e-e2cc8792592e', '{"level":"discipline-facet","facet_of":"Innovation","definition":"An individual finds a new solution to a problem, usually by trial and error and sometimes by apparent insight. Animals do this in many species, for example when they exploit a new food source. It can aim at a goal.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-innovation-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('69dd42eb-2b99-51bd-a983-32444ae17c62', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Innovation (culture)', 'A new practice, word, belief or artifact enters a community''s repertoire, by invention or by recombining old ideas. Many innovations are small changes to existing ones.', '183d2755-1489-554c-9b9e-e2cc8792592e', '{"level":"discipline-facet","facet_of":"Innovation","definition":"A new practice, word, belief or artifact enters a community''s repertoire, by invention or by recombining old ideas. Many innovations are small changes to existing ones.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-innovation-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b3730960-c588-5975-946b-0aa4de567677', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Innovation (technology)', 'A new device, method or material is invented, often by combining existing parts or principles in a new way. Deliberate search and testing guide many inventions.', '183d2755-1489-554c-9b9e-e2cc8792592e', '{"level":"discipline-facet","facet_of":"Innovation","definition":"A new device, method or material is invented, often by combining existing parts or principles in a new way. Deliberate search and testing guide many inventions.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-innovation-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('7aef644c-0165-587f-9db1-104671c0a5d7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Innovation (AI and computation)', 'Mutation randomly changes a candidate and crossover swaps parts between two candidates, producing new candidates. Some methods reward novelty itself, instead of the score or alongside it.', '183d2755-1489-554c-9b9e-e2cc8792592e', '{"level":"discipline-facet","facet_of":"Innovation","definition":"Mutation randomly changes a candidate and crossover swaps parts between two candidates, producing new candidates. Some methods reward novelty itself, instead of the score or alongside it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-innovation-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Development
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Change in one individual over its own lifetime, in which later states build on earlier ones. It comes from growth and from interaction with the setting, and it often follows a typical sequence.","excludes":"Development is not a kind of evolution. A growing organism does not evolve, and a population does not grow up. The link is causal: development turns inherited information into a body and responds to conditions, which shapes the variants selection sees. Software development is another sense.","core_counterparts":[],"curriculum_use":"Grade 1-2 Sachunterricht (Entwicklungsstadien von Blütenpflanzen, Keimung und Wachstum), grade 8 Biologie (vorgeburtliche Entwicklung, Individualentwicklung), and learner growth in any subject.","grounding":["OE-CONCEPT-oe-interdisciplinary-development","OE-CONCEPT-openevo-design-concept-child-development","ISBN 9780195122343 (West-Eberhard 2003, Developmental Plasticity and Evolution; Open Library-checked)","doi:10.1002/bies.202100185 (Sultan, Moczek & Walsh 2022; Crossref-checked)","doi:10.1016/j.dr.2015.07.004 (Barrouillet 2015; Crossref-checked)","doi:10.1080/09540090310001655110 (Lungarella et al. 2003; Crossref-checked)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '0254d031-dbdf-5a23-ab7b-c5046e0ac80f';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2e258b11-a359-5e90-aed9-f2a14d2923f7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Development (biology)', 'An organism grows from egg or seed to adult through cell division, specialization of cells and interaction with its surroundings. Genes and conditions together shape the outcome, and some traits respond to conditions during growth.', '0254d031-dbdf-5a23-ab7b-c5046e0ac80f', '{"level":"discipline-facet","facet_of":"Development","definition":"An organism grows from egg or seed to adult through cell division, specialization of cells and interaction with its surroundings. Genes and conditions together shape the outcome, and some traits respond to conditions during growth.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-development-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('14947e20-aa6f-5213-a149-3e44ab6f6f0e', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Development (cognition)', 'A child''s thinking, language and social understanding change with age and experience, often in a typical order. Maturation, social interaction and cultural learning all contribute.', '0254d031-dbdf-5a23-ab7b-c5046e0ac80f', '{"level":"discipline-facet","facet_of":"Development","definition":"A child''s thinking, language and social understanding change with age and experience, often in a typical order. Maturation, social interaction and cultural learning all contribute.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-development-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ca5836d1-01bb-5b22-bb2a-fbe3b1c8d61a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Development (education)', 'The progressive growth of a learner''s knowledge, skills or competencies over time, often supported by instruction that is gradually withdrawn (scaffolding).', '0254d031-dbdf-5a23-ab7b-c5046e0ac80f', '{"level":"discipline-facet","facet_of":"Development","definition":"The progressive growth of a learner''s knowledge, skills or competencies over time, often supported by instruction that is gradually withdrawn (scaffolding).","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-development-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c83f55c6-5b8f-5e4f-949b-972a91ff799d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Development (AI and computation)', 'Analogy only. Developmental robotics trains a robot in stages modelled on child development. The robot does not grow or mature, and its designers choose the stages.', '0254d031-dbdf-5a23-ab7b-c5046e0ac80f', '{"level":"discipline-facet","facet_of":"Development","definition":"Analogy only. Developmental robotics trains a robot in stages modelled on child development. The robot does not grow or mature, and its designers choose the stages.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-development-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Agency
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"The capacity of an entity to sense its setting and respond flexibly in pursuit of its own aims, so that its actions change what happens next. Intention is one form of this capacity, found in some domains.","excludes":"Intention and reasons belong to the human and cognition senses and are absent in bacteria and plants. Software has designer-set goals. A species, evolution or a gene is not an agent. Organism agency does not make variants arise to meet a need. Agency comes in degrees.","core_counterparts":[{"space":"soc","label":"Agency","relation":"broader"}],"curriculum_use":"Describes organisms as active in niche construction and behaviour units (Biologie), citizens acting within rules (Ethik, Gemeinschaftskunde), and software agents in AI units, and flags where agent language misleads.","grounding":["OE-CONCEPT-oe-interdisciplinary-agency","OE-PROPOSITION-agency-legitimate-in-many-cases","OE-MISCONCEPTION-agency-negation","OE-DIVERGENCE-role-of-organism-agency","OE-DESIGNPRINCIPLE-behaviorally-mediated-selection-first-class","doi:10.1002/bies.202100185 (Sultan, Moczek & Walsh 2022; Crossref-checked)","doi:10.1111/ede.12448 (Walsh & Rupik 2023; Crossref-checked)","ISBN 9781107122109 (Walsh 2015, Organisms, Agency, and Evolution; Open Library-checked)","doi:10.1098/rspb.2015.1019 (Laland et al. 2015; Crossref-checked)","doi:10.1111/j.1745-6916.2006.00011.x (Bandura 2006; Crossref-checked)","doi:10.1086/231294 (Emirbayer & Mische 1998; Crossref-checked)","ISBN 9780134610993 (Russell & Norvig 2020, Artificial Intelligence: A Modern Approach; Open Library-checked)","ConceptBase OE-CONCEPT-oe-interdisciplinary-agency","ConceptBase AI4K12 OE-COMPETENCY-000263 (an intelligent agent)","DOI 10.1080/00219266.2025.2486963 (Hanisch, Eirdosh & González Galli 2025, Crossref checked; LiteratureBase OE-LITERATURE-hanisch-2025)","DOI 10.1002/bies.202100185 (Sultan, Moczek & Walsh 2021, Crossref checked; LiteratureBase OE-LITERATURE-sultan-2022)","LiteratureBase OE-LITERATURE-ariew-panchanathan-2023 and OE-LITERATURE-moore-et-al-2002 (agency ascribed to evolution as a learning problem)","DOI 10.1111/j.1745-6916.2006.00011.x (Bandura 2006, Crossref checked)","DOI 10.1017/S0269888900008122 (Wooldridge & Jennings 1995, Crossref checked)","DOI 10.1017/cbo9781316402719.001 (Walsh, Organisms, Agency, and Evolution, front-matter record, Crossref checked)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '993c989a-79d2-5262-b20f-9636504623cd';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1e6fa81c-df61-51b7-9657-94a4337f4168', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Agency (biology)', 'Organisms act to keep themselves going: they seek food, choose habitats and change their surroundings. On the organismal-agency view, this needs no intention, planning or awareness. It alters the pressures later generations face (niche construction).', '993c989a-79d2-5262-b20f-9636504623cd', '{"level":"discipline-facet","facet_of":"Agency","definition":"Organisms act to keep themselves going: they seek food, choose habitats and change their surroundings. On the organismal-agency view, this needs no intention, planning or awareness. It alters the pressures later generations face (niche construction).","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-agency-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('65346a4d-bc5d-5e85-97ca-3a6ceef70bba', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Agency (culture)', 'People act for reasons, plan and weigh options, but within limits set by resources, rules and other people''s actions. Groups and organisations act through their members'' decisions. Their choices can reproduce or change those limits over time.', '993c989a-79d2-5262-b20f-9636504623cd', '{"level":"discipline-facet","facet_of":"Agency","definition":"People act for reasons, plan and weigh options, but within limits set by resources, rules and other people''s actions. Groups and organisations act through their members'' decisions. Their choices can reproduce or change those limits over time.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-agency-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2023288d-24f1-5bdc-8c5e-e0f459434fef', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Agency (cognition)', 'A person acts intentionally: forms intentions, plans ahead, regulates their own action and reflects on whether the plan works (Bandura''s four core properties). This form of agency needs a represented goal.', '993c989a-79d2-5262-b20f-9636504623cd', '{"level":"discipline-facet","facet_of":"Agency","definition":"A person acts intentionally: forms intentions, plans ahead, regulates their own action and reflects on whether the plan works (Bandura''s four core properties). This form of agency needs a represented goal.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-agency-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b813207c-5cb3-55a8-937e-3bb49941a354', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Agency (education)', 'A learner sets goals, chooses strategies, monitors progress and takes responsibility for learning. Teachers support agency by giving meaningful choices and gradually reducing guidance.', '993c989a-79d2-5262-b20f-9636504623cd', '{"level":"discipline-facet","facet_of":"Agency","definition":"A learner sets goals, chooses strategies, monitors progress and takes responsibility for learning. Teachers support agency by giving meaningful choices and gradually reducing guidance.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-agency-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('a0a9b3c7-0521-5e1a-812f-c8aff147b9bc', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Agency (AI and computation)', 'Technical reading: a software or robot agent senses its setting and selects actions to reach goals set by its designer. It holds no reasons of its own, and others can change its goals.', '993c989a-79d2-5262-b20f-9636504623cd', '{"level":"discipline-facet","facet_of":"Agency","definition":"Technical reading: a software or robot agent senses its setting and selects actions to reach goals set by its designer. It holds no reasons of its own, and others can change its goals.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-agency-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Transmission
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"The process by which information, traits or practices move from one holder (organism, person, group or system) to another, so that the receiver ends up with something similar to what the sender had.","excludes":"Fidelity differs. DNA copying and file copying are nearly exact. Human learning often rebuilds what it receives. Biological transmission runs mainly from parent to offspring. Culture and technology also allow transmission between peers and from many sources. A learner brings prior ideas, so understanding can differ from what was taught.","core_counterparts":[{"space":"bio","label":"Inheritance","relation":"broader"},{"space":"soc","label":"Diffusion","relation":"broader"}],"curriculum_use":"Grade 10 Genetik (Weitergabe der Erbanlagen), grade 5 Säugetiere (Sender-Empfänger-Modell), spread of ideas in Geschichte, and grade 9 Informatik Netzwerke (Datenpakete).","grounding":["OE-CONCEPT-oe-interdisciplinary-transmission","OE-CONCEPT-oe-interdisciplinary-inheritance","ISBN 9780691082806 (Cavalli-Sforza & Feldman 1981; Open Library-checked)","ISBN 9780691044378 (Odling-Smee, Laland & Feldman 2003; Open Library-checked)","doi:10.1016/j.jaa.2005.08.001 (Eerkens & Lipo 2005; Crossref-checked)","arXiv:1503.02531 (Hinton, Vinyals & Dean 2015, Distilling the knowledge in a neural network; arXiv API-checked)","ISBN 9780631200444 (Sperber 1996, Explaining Culture; listed by Open Library, edition not matched)","unverified: education facet rests on the constructivist view of learning; no source retrieved"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '0a1dc107-eeca-53a2-8a29-056c0f7b70df';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e38e793a-4978-5bba-a960-749d4aeb696a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Transmission (biology)', 'Genes pass from parents to offspring through eggs, sperm or cell division. Some microbes also pass genes sideways to unrelated cells. Parents can also pass on a made environment such as a nest or burrow.', '0a1dc107-eeca-53a2-8a29-056c0f7b70df', '{"level":"discipline-facet","facet_of":"Transmission","definition":"Genes pass from parents to offspring through eggs, sperm or cell division. Some microbes also pass genes sideways to unrelated cells. Parents can also pass on a made environment such as a nest or burrow.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-transmission-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('eae468b6-00ce-5629-afd2-1696388dce72', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Transmission (culture)', 'Practices pass between people by social learning: from parents, from peers and from older non-relatives. Imitation, teaching and language carry them. Learners often rebuild what they learn, so practices can change in passing.', '0a1dc107-eeca-53a2-8a29-056c0f7b70df', '{"level":"discipline-facet","facet_of":"Transmission","definition":"Practices pass between people by social learning: from parents, from peers and from older non-relatives. Imitation, teaching and language carry them. Learners often rebuild what they learn, so practices can change in passing.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-transmission-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('cab6a811-7b63-5b9d-ae89-ed47c0366150', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Transmission (technology)', 'Designs pass by copying drawings, code or products, by training apprentices and by taking a device apart to see how it works. A copied file can be exact. A copied skill usually is not.', '0a1dc107-eeca-53a2-8a29-056c0f7b70df', '{"level":"discipline-facet","facet_of":"Transmission","definition":"Designs pass by copying drawings, code or products, by training apprentices and by taking a device apart to see how it works. A copied file can be exact. A copied skill usually is not.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-transmission-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('26e6bee3-4d18-53e4-8c65-e7195b37b833', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Transmission (AI and computation)', 'Data and trained models are copied exactly between machines. A smaller model can also be trained to imitate a larger one (distillation), which passes on behavior without copying its inner parts.', '0a1dc107-eeca-53a2-8a29-056c0f7b70df', '{"level":"discipline-facet","facet_of":"Transmission","definition":"Data and trained models are copied exactly between machines. A smaller model can also be trained to imitate a larger one (distillation), which passes on behavior without copying its inner parts.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-transmission-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('156cc037-6c7c-5420-9d48-a77e314d595c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Transmission (education)', 'A teacher explains, demonstrates and sets tasks, and the learner rebuilds the knowledge. What arrives is the learner''s own version, so understanding can differ from what was taught.', '0a1dc107-eeca-53a2-8a29-056c0f7b70df', '{"level":"discipline-facet","facet_of":"Transmission","definition":"A teacher explains, demonstrates and sets tasks, and the learner rebuilds the knowledge. What arrives is the learner''s own version, so understanding can differ from what was taught.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-transmission-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Adaptation
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f68a7cc1-f7dc-5c78-83a7-bccdb1ebad62', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Adaptation', 'A feature of a system that fits the demands of its setting, together with whatever process made it fit. The fit can be observed on its own. The process differs by domain: selection over generations, adjustment within a lifetime, or deliberate design.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"definition":"A feature of a system that fits the demands of its setting, together with whatever process made it fit. The fit can be observed on its own. The process differs by domain: selection over generations, adjustment within a lifetime, or deliberate design.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-adaptation","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Fit today does not show that selection built it. A trait selected for another use, or a by-product, can also fit. Lifetime adjustment is not inherited. Individuals can adjust to need, but populations do not evolve traits because individuals need them. In design and computing a person sets the target.","core_counterparts":[{"space":"bio","label":"Adaptation","relation":"broader"},{"space":"bio","label":"Fitness","relation":"related"},{"space":"bio","label":"Natural Selection","relation":"related"},{"space":"comp","label":"Search","relation":"related"}],"curriculum_use":"Sachsen teaches Angepasstheit as a fit of structure to habitat in grades 4-6 (Fische, Lurche, Vögel, Säugetiere) and links it to selection only in grade 10 (Entstehung der Artenvielfalt, Vogelschnäbel).","grounding":["OE-CONCEPT-bio-core-adaptation","OE-CURRICULUMDECISION-bio-core-natural-selection-decentralized-vocabulary-only","doi:10.1098/rsbl.2009.0674 (Gardner 2009, Adaptation as organism design; Crossref-checked)","doi:10.1017/S0094837300004310 (Gould & Vrba 1982, Exaptation; Crossref-checked)","ISBN 9780691026152 (Williams, Adaptation and Natural Selection; Open Library-checked)","doi:10.1017/S0140525X00002417 (Laland, Odling-Smee & Feldman 2000; Crossref-checked)","ISBN 9780691166858 (Henrich 2016, The Secret of Our Success; Open Library-checked)","ISBN 9780226712840 (Richerson & Boyd 2005, book titled Not by Genes Alone; Open Library-checked)","ISBN 9780521296816 (Basalla 1988, The Evolution of Technology; Open Library-checked)","ISBN 9780262581110 (Holland, Adaptation in Natural and Artificial Systems; Open Library-checked)","ISBN 9780262631853 (Mitchell, An Introduction to Genetic Algorithms; Open Library-checked)","ISBN 9780195122343 (West-Eberhard 2003, Developmental Plasticity and Evolution; Open Library-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7601-1 (Biologie grade 10, Entstehung der Artenvielfalt; read in the topic cache)","Sachsen Lehrplan topic lehrplan-80-1/lernbereich-6293-1 (Sachunterricht grade 4, Beispiele fuer Angepasstheit; read in the topic cache)","unverified: Piaget (1952) uses adaptation for assimilation and accommodation. I did not retrieve it and the facets do not rely on it"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0beb440f-9280-5d38-a196-18c7f6869fc0', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Adaptation (biology)', 'A heritable trait that natural selection built for its function, such as camouflage. Angepasstheit (adaptedness) is the fit of structure to habitat seen today, whatever its origin. Adaptations are the fits that selection explains; other fits have other causes.', 'f68a7cc1-f7dc-5c78-83a7-bccdb1ebad62', '{"level":"discipline-facet","facet_of":"Adaptation","definition":"A heritable trait that natural selection built for its function, such as camouflage. Angepasstheit (adaptedness) is the fit of structure to habitat seen today, whatever its origin. Adaptations are the fits that selection explains; other fits have other causes.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-adaptation-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('831c4126-6285-5300-9dab-88f4d298437c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Adaptation (culture)', 'A practice or tool whose form suits local conditions. Researchers argue that this comes from keeping and copying variants that worked, as with ways of making toxic food crops safe to eat. Users often cannot say why it works.', 'f68a7cc1-f7dc-5c78-83a7-bccdb1ebad62', '{"level":"discipline-facet","facet_of":"Adaptation","definition":"A practice or tool whose form suits local conditions. Researchers argue that this comes from keeping and copying variants that worked, as with ways of making toxic food crops safe to eat. Users often cannot say why it works.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-adaptation-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2800ca93-2b48-51f8-9966-1620a8b422f3', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Adaptation (technology)', 'A design whose features suit its use and operating conditions. It is reached by trying variants and copying those that perform, or by deliberate engineering. The measure of fit is the job the design must do.', 'f68a7cc1-f7dc-5c78-83a7-bccdb1ebad62', '{"level":"discipline-facet","facet_of":"Adaptation","definition":"A design whose features suit its use and operating conditions. It is reached by trying variants and copying those that perform, or by deliberate engineering. The measure of fit is the job the design must do.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-adaptation-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8c945da2-12bf-573a-9c44-372bd1a4daec', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Adaptation (AI and computation)', 'A candidate solution whose encoded features score well against a fixed objective, reached by rounds of variation, scoring and copying in an evolutionary algorithm. The designer picks the objective and so defines what counts as fit.', 'f68a7cc1-f7dc-5c78-83a7-bccdb1ebad62', '{"level":"discipline-facet","facet_of":"Adaptation","definition":"A candidate solution whose encoded features score well against a fixed objective, reached by rounds of variation, scoring and copying in an evolutionary algorithm. The designer picks the objective and so defines what counts as fit.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-adaptation-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1813a6a5-003d-5f41-b0ee-f2af4484587d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Adaptation (cognition)', 'A learner or animal revises behavior after experience so that it suits current conditions. The adjustment belongs to that individual and lasts at most one lifetime. Offspring do not inherit it.', 'f68a7cc1-f7dc-5c78-83a7-bccdb1ebad62', '{"level":"discipline-facet","facet_of":"Adaptation","definition":"A learner or animal revises behavior after experience so that it suits current conditions. The adjustment belongs to that individual and lasts at most one lifetime. Offspring do not inherit it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-adaptation-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Fitness
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2208c511-0a4b-59ad-a8cf-78bde2588a95', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Fitness', 'How well a variant does, compared with its alternatives, at being kept and passed on in a given setting. What is counted depends on the domain: offspring, adopters or a score.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"definition":"How well a variant does, compared with its alternatives, at being kept and passed on in a given setting. What is counted depends on the domain: offspring, adopters or a score.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-fitness","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Biological fitness is estimated from offspring counts and depends on the environment. In computing a designer usually assigns it beforehand. Cultural success can follow learners'' biases and can harm adopters. Fitness always compares a variant with rivals in a stated setting.","core_counterparts":[{"space":"bio","label":"Fitness","relation":"broader"},{"space":"bio","label":"Natural Selection","relation":"related"},{"space":"comp","label":"Search","relation":"related"}],"curriculum_use":"Grade 10 Biologie ''Entstehung der Artenvielfalt'' (hints: Fitness, Reproduktionserfolg), the spread of practices in Geschichte, and scoring rules for candidate solutions.","grounding":["OE-CONCEPT-bio-core-fitness","doi:10.1038/nrg2603 (Orr 2009, Fitness and its role in evolutionary genetics; Crossref-checked)","doi:10.1086/288865 (Mills & Beatty 1979, The propensity interpretation of fitness; Crossref-checked)","doi:10.1002/evan.10110 (Henrich & McElreath 2003; Crossref-checked)","ISBN 9780226069333 (Boyd & Richerson, Culture and the Evolutionary Process; Open Library-checked)","doi:10.1016/B978-0-08-050684-5.50008-2 (Goldberg & Deb 1991, selection schemes in genetic algorithms; Crossref-checked)","ISBN 9780262631853 (Mitchell, An Introduction to Genetic Algorithms; Open Library-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7601-1 (Biologie grade 10, Entstehung der Artenvielfalt; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('89b15785-7f77-5946-97c3-dd591d567c1f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Fitness (biology)', 'Relative reproductive success: the average number of offspring that individuals of a type leave, compared with other types in the same setting. Strength or health matter only through their effect on offspring numbers.', '2208c511-0a4b-59ad-a8cf-78bde2588a95', '{"level":"discipline-facet","facet_of":"Fitness","definition":"Relative reproductive success: the average number of offspring that individuals of a type leave, compared with other types in the same setting. Strength or health matter only through their effect on offspring numbers.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-fitness-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('031430b2-b794-5149-9458-b6b839c35cd0', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Fitness (culture)', 'How often a practice or belief is learned and kept by others, compared with rival variants. It depends on ease of learning, apparent usefulness and who holds it. A popular practice can harm those who adopt it.', '2208c511-0a4b-59ad-a8cf-78bde2588a95', '{"level":"discipline-facet","facet_of":"Fitness","definition":"How often a practice or belief is learned and kept by others, compared with rival variants. It depends on ease of learning, apparent usefulness and who holds it. A popular practice can harm those who adopt it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-fitness-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('13175cde-b4d9-596d-9e73-167dc35cc503', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Fitness (AI and computation)', 'A number a program assigns to each candidate solution to show how well it meets the objective. The score decides which candidates are copied or varied next. The programmer usually defines it before the run starts.', '2208c511-0a4b-59ad-a8cf-78bde2588a95', '{"level":"discipline-facet","facet_of":"Fitness","definition":"A number a program assigns to each candidate solution to show how well it meets the objective. The score decides which candidates are copied or varied next. The programmer usually defines it before the run starts.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-fitness-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Population
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9d57c506-0a8e-50e0-b5a5-6db1f8908e29', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Population', 'A set of members counted together because they vary and affect one another''s chances of being copied. Change over time is described as a shift in the mix of variants across the set. No single member needs to change for the set to change.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"definition":"A set of members counted together because they vary and affect one another''s chances of being copied. Change over time is described as a shift in the mix of variants across the set. No single member needs to change for the set to change.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-population","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Interbreeding defines a biological population only. A cultural population is defined by who copies whom, and populations overlap. A program''s population has a size set by the programmer. Population thinking treats differences among members as the data, so a population is never one typical member repeated.","core_counterparts":[{"space":"bio","label":"Population","relation":"broader"}],"curriculum_use":"Grade 10 Biologie ''Populationsbegriff'' (Entstehung der Artenvielfalt), grade 9 Zusammenhänge im Ökosystem, and counts of names, styles or designs across a community.","grounding":["OE-CONCEPT-bio-core-population","doi:10.1086/288942 (Sober 1980, Population thinking; Crossref-checked)","doi:10.1093/genetics/16.2.97 (Wright 1931; Crossref-checked)","ISBN 9780199552047 (Godfrey-Smith 2009, Darwinian Populations and Natural Selection; Open Library-checked)","doi:10.1098/rspb.2004.2746 (Bentley, Hahn & Shennan 2004; Crossref-checked)","doi:10.1016/j.jas.2009.12.039 (Steele, Glatz & Kandler 2010; Crossref-checked)","ISBN 9780262631853 (Mitchell, An Introduction to Genetic Algorithms; Open Library-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7601-1 (Biologie grade 10, Entstehung der Artenvielfalt; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('af0f5311-7248-50eb-bf18-df8cc6e3dfd5', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Population (biology)', 'Interbreeding organisms of one species in a place and time. Members share a gene pool, so their alleles mix each generation. Evolution is a change in how common alleles or traits are in this group.', '9d57c506-0a8e-50e0-b5a5-6db1f8908e29', '{"level":"discipline-facet","facet_of":"Population","definition":"Interbreeding organisms of one species in a place and time. Members share a gene pool, so their alleles mix each generation. Evolution is a change in how common alleles or traits are in this group.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-population-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bb8d6064-e4ec-58b9-99be-c04ff7e80880', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Population (culture)', 'The people who can learn from one another, such as a village or an online community. Who copies whom sets the boundary, so one person belongs to several. Researchers count variants, such as first names or pottery styles.', '9d57c506-0a8e-50e0-b5a5-6db1f8908e29', '{"level":"discipline-facet","facet_of":"Population","definition":"The people who can learn from one another, such as a village or an online community. Who copies whom sets the boundary, so one person belongs to several. Researchers count variants, such as first names or pottery styles.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-population-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ec00c40a-b845-54a3-9994-3cc55b1221bc', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Population (technology)', 'All versions of a design in use or on record, such as the car models on the road or the pottery found at a site. Counts of each version show which designs spread or vanish.', '9d57c506-0a8e-50e0-b5a5-6db1f8908e29', '{"level":"discipline-facet","facet_of":"Population","definition":"All versions of a design in use or on record, such as the car models on the road or the pottery found at a site. Counts of each version show which designs spread or vanish.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-population-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('687ad7fa-e148-5731-af29-00dd09e7cba7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Population (AI and computation)', 'The pool of candidate solutions in an evolutionary algorithm. The programmer chooses its size, which usually stays fixed. Each round replaces the pool with a new one built from the better candidates.', '9d57c506-0a8e-50e0-b5a5-6db1f8908e29', '{"level":"discipline-facet","facet_of":"Population","definition":"The pool of candidate solutions in an evolutionary algorithm. The programmer chooses its size, which usually stays fixed. Each round replaces the pool with a new one built from the better candidates.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-population-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Drift
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9d453241-76de-5f5e-be7e-ee6f4e7e898d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Drift', 'Change in how common a variant is that comes from chance in which copies get passed on. It needs no advantage for the variant and is strongest in small populations. Drift can remove variants and can make rare variants common.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"definition":"Change in how common a variant is that comes from chance in which copies get passed on. It needs no advantage for the variant and is strongest in small populations. Drift can remove variants and can make rare variants common.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-drift","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"A fit to a random-copying model does not prove random copying, because other processes can give the same counts. Many people copy with biases such as prestige, which acts like selection. Drift in computing comes from pool size. Drift acts on a set and never on one individual.","core_counterparts":[{"space":"bio","label":"Drift","relation":"broader"}],"curriculum_use":"Grade 10 Biologie ''Entstehung der Artenvielfalt'' (Veränderung der Arten), the chance side of population genetics, and chance in how names, styles or designs spread.","grounding":["OE-CONCEPT-bio-core-drift","doi:10.1093/genetics/16.2.97 (Wright 1931; Crossref-checked)","doi:10.1093/genetics/47.6.713 (Kimura 1962; Crossref-checked)","doi:10.1098/rsbl.2003.0045 (Hahn & Bentley 2003; Crossref-checked)","doi:10.1098/rspb.2004.2746 (Bentley, Hahn & Shennan 2004; Crossref-checked)","doi:10.1016/j.jas.2009.12.039 (Steele, Glatz & Kandler 2010; Crossref-checked)","doi:10.1109/4235.797972 (Rogers & Prugel-Bennett 1999, Genetic drift in genetic algorithm selection schemes; Crossref-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7601-1 (Biologie grade 10, Entstehung der Artenvielfalt; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4611d7f3-5aca-5b19-af26-fb2ade476172', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Drift (biology)', 'Allele frequencies shift from one generation to the next because the parents that happen to reproduce are a random sample. In small populations an allele can disappear or take over without any advantage.', '9d453241-76de-5f5e-be7e-ee6f4e7e898d', '{"level":"discipline-facet","facet_of":"Drift","definition":"Allele frequencies shift from one generation to the next because the parents that happen to reproduce are a random sample. In small populations an allele can disappear or take over without any advantage.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-drift-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d39c19a2-3136-5f6f-9398-6d184c2e7bfb', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Drift (culture)', 'When people copy at random from those around them, the popularity of baby names, pottery styles or other variants rises and falls by chance. Random-copying models fit several such records.', '9d453241-76de-5f5e-be7e-ee6f4e7e898d', '{"level":"discipline-facet","facet_of":"Drift","definition":"When people copy at random from those around them, the popularity of baby names, pottery styles or other variants rises and falls by chance. Random-copying models fit several such records.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-drift-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('3a995867-e5aa-5004-802d-d4bd8dd991d0', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Drift (technology)', 'Which of several similar designs becomes common can depend on chance in early adoption. A random-copying model fits counts of technology patent applications, which suggests chance can decide this. Other processes could give the same counts.', '9d453241-76de-5f5e-be7e-ee6f4e7e898d', '{"level":"discipline-facet","facet_of":"Drift","definition":"Which of several similar designs becomes common can depend on chance in early adoption. A random-copying model fits counts of technology patent applications, which suggests chance can decide this. Other processes could give the same counts.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-drift-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('fcace33b-a4ee-5ca5-8b51-3248f28f8ea4', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Drift (AI and computation)', 'In a genetic algorithm with a small pool, features can spread or vanish by luck in which candidates get picked to reproduce, even when scores are equal. This can end the search early.', '9d453241-76de-5f5e-be7e-ee6f4e7e898d', '{"level":"discipline-facet","facet_of":"Drift","definition":"In a genetic algorithm with a small pool, features can spread or vanish by luck in which candidates get picked to reproduce, even when scores are equal. This can end the search early.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-drift-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Selection Pressure
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f133d4d2-44ee-5c33-83be-5de3d93cd061', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Selection Pressure', 'A factor that makes some variants more likely than others to be kept and passed on, and so sets the direction in which the mix of variants shifts. It acts on the mix across a population and gives individuals no push to change.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"definition":"A factor that makes some variants more likely than others to be kept and passed on, and so sets the direction in which the mix of variants shifts. It acts on the mix across a population and gives individuals no push to change.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-selection-pressure","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"In biology a pressure is a factor in the setting. In computing it is the strength of a rule a programmer chose, a different quantity. A pressure changes which variants are kept and makes no individual change or try to change. Cultural pressures include learners'' own preferences.","core_counterparts":[{"space":"bio","label":"Selection Pressure","relation":"broader"},{"space":"bio","label":"Natural Selection","relation":"related"},{"space":"comp","label":"Search","relation":"related"}],"curriculum_use":"Grade 9 Biologie Zusammenhänge im Ökosystem (Konkurrenz), grade 10 Entstehung der Artenvielfalt, and why some practices or designs persist.","grounding":["OE-CONCEPT-bio-core-selection-pressure","doi:10.1038/nrg2603 (Orr 2009, Fitness and its role in evolutionary genetics; Crossref-checked)","doi:10.1002/evan.10110 (Henrich & McElreath 2003; Crossref-checked)","ISBN 9780226069333 (Boyd & Richerson, Culture and the Evolutionary Process; Open Library-checked)","ISBN 9780226712840 (Richerson & Boyd 2005, book titled Not by Genes Alone; Open Library-checked)","doi:10.1109/ICEC.1994.350042 (Back 1994, Selective pressure in evolutionary algorithms; Crossref-checked)","doi:10.1016/B978-0-08-050684-5.50008-2 (Goldberg & Deb 1991, selection schemes in genetic algorithms; Crossref-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7601-1 (Biologie grade 10, Entstehung der Artenvielfalt; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('260e2351-c89a-55b4-ad74-f5e31b4c99f7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Selection Pressure (biology)', 'A feature of the surroundings or of other organisms that changes survival or reproduction of variants, such as predators, drought, disease, food supply or rivals for mates. Its strength shows in how much survival or reproduction differs among variants.', 'f133d4d2-44ee-5c33-83be-5de3d93cd061', '{"level":"discipline-facet","facet_of":"Selection Pressure","definition":"A feature of the surroundings or of other organisms that changes survival or reproduction of variants, such as predators, drought, disease, food supply or rivals for mates. Its strength shows in how much survival or reproduction differs among variants.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-selection-pressure-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4d6bb400-67de-5fbc-bb96-2483a1c090f0', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Selection Pressure (culture)', 'Conditions that make some practices easier to keep and pass on: climate and resources, laws and prices, and the learning biases of the people who copy, such as favoring prestigious models.', 'f133d4d2-44ee-5c33-83be-5de3d93cd061', '{"level":"discipline-facet","facet_of":"Selection Pressure","definition":"Conditions that make some practices easier to keep and pass on: climate and resources, laws and prices, and the learning biases of the people who copy, such as favoring prestigious models.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-selection-pressure-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f93755db-8051-535d-9c72-789b51e3e013', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Selection Pressure (AI and computation)', 'In an evolutionary algorithm, selection pressure is how strongly the selection rule favors higher scorers, for example by letting only the best few of a random sample become parents. The programmer sets it, and high pressure reduces variety.', 'f133d4d2-44ee-5c33-83be-5de3d93cd061', '{"level":"discipline-facet","facet_of":"Selection Pressure","definition":"In an evolutionary algorithm, selection pressure is how strongly the selection rule favors higher scorers, for example by letting only the best few of a random sample become parents. The programmer sets it, and high pressure reduces variety.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-selection-pressure-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Extinction
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2b7d0910-2336-5d30-ba81-03bddbaae9fb', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Extinction', 'The end of a lineage: a kind of thing that was once passed on stops being passed on, so no later copies exist. Causes include loss of holders, failure to reproduce and an end to copying.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"definition":"The end of a lineage: a kind of thing that was once passed on stops being passed on, so no later copies exist. Causes include loss of holders, failure to reproduce and an end to copying.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-extinction","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"A species cannot return, while languages and techniques can sometimes be revived from records and learners. Cultural loss does not need the holders to die, because they may adopt another language or tool. A fall in numbers is not yet extinction. Software and file-format obsolescence is left out.","core_counterparts":[{"space":"bio","label":"Extinction","relation":"broader"}],"curriculum_use":"Grade 5 Biologie Kriechtiere (ausgestorbene Kriechtiere), Fossilien in grade 10, and loss of languages or old crafts if a topic raises them.","grounding":["OE-CONCEPT-bio-core-extinction","doi:10.1038/s41559-021-01604-y (Bromham et al., Global predictors of language endangerment, Nature Ecology & Evolution; Crossref-checked)","ISBN 9780195152463 (Nettle & Romaine, Vanishing Voices; Open Library-checked)","doi:10.2307/4128416 (Henrich 2004, Tasmanian case; Crossref-checked)","doi:10.1073/pnas.1520288113 (Vaesen et al. 2016; Crossref-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7066-1 (Biologie grade 5, Kriechtiere in ihren Lebensräumen, ausgestorbene Kriechtiere; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6a181f40-867e-59ad-a0a4-a2c8b52effc3', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Extinction (biology)', 'A species ends when its last member dies without leaving offspring. Common causes include habitat loss, climate change, hunting and disease.', '2b7d0910-2336-5d30-ba81-03bddbaae9fb', '{"level":"discipline-facet","facet_of":"Extinction","definition":"A species ends when its last member dies without leaving offspring. Common causes include habitat loss, climate change, hunting and disease.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-extinction-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8152e3c0-83b1-55ad-8545-b74ad7da7222', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Extinction (culture)', 'A language goes extinct when its last speakers die or when the community stops passing it to children. Studies of thousands of languages test predictors such as road density and years of schooling.', '2b7d0910-2336-5d30-ba81-03bddbaae9fb', '{"level":"discipline-facet","facet_of":"Extinction","definition":"A language goes extinct when its last speakers die or when the community stops passing it to children. Studies of thousands of languages test predictors such as road density and years of schooling.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-extinction-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('dd9db45f-054e-51fe-a0b6-864f7c2f42d3', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Extinction (technology)', 'A technique is lost when no one who can make it remains and no record survives. Tasmanian tool loss is debated: one model blames a small isolated population, and a later study doubts that population size explains such losses.', '2b7d0910-2336-5d30-ba81-03bddbaae9fb', '{"level":"discipline-facet","facet_of":"Extinction","definition":"A technique is lost when no one who can make it remains and no record survives. Tasmanian tool loss is debated: one model blames a small isolated population, and a later study doubts that population size explains such losses.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-extinction-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Descent
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e0a89c95-8625-539f-93ef-ac864737144a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Descent', 'Links between earlier and later versions through reproduction or copying, so that shared features can be traced to a shared origin. Where one line splits in two, descendants share an ancestor and differ by what changed afterwards. Relatedness can be drawn as a branching tree.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"definition":"Links between earlier and later versions through reproduction or copying, so that shared features can be traced to a shared origin. Where one line splits in two, descendants share an ancestor and differ by what changed afterwards. Relatedness can be drawn as a branching tree.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-descent","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Biological descent runs mostly from parent to offspring, so a tree fits well for most animals. Microbes, languages, texts and designs borrow across lines, so a tree fits only partly. Shared features can come from shared ancestry or from independent solutions. A tree has no ladder or main line.","core_counterparts":[{"space":"bio","label":"Common Ancestor","relation":"broader"},{"space":"bio","label":"Phylogeny","relation":"broader"},{"space":"bio","label":"Common Descent and Deep Time","relation":"related"}],"curriculum_use":"Grade 10 Biologie ''Stammesgeschichte des Menschen'' (Modell zum Hominidenstammbaum), Homologien and Zwischenformen, and language families if a topic raises them.","grounding":["OE-CONCEPT-bio-core-common-ancestor","OE-CONCEPT-bio-core-phylogeny","OE-SANDBOX-CONCEPT-000003","doi:10.1038/29667 (Barbrook et al. 1998, The phylogeny of The Canterbury Tales; Crossref-checked)","doi:10.1038/nature02029 (Gray & Atkinson 2003; Crossref-checked)","doi:10.1080/10635150590950317 (Atkinson & Gray 2005; Crossref-checked)","doi:10.1126/science.1219669 (Bouckaert et al. 2012; Crossref-checked)","doi:10.1016/j.tree.2004.12.002 (Mace & Holden 2005; Crossref-checked)","doi:10.1371/journal.pbio.1001069 (Howe & Windram 2011; Crossref-checked)","doi:10.1038/nrg2560 (Pagel 2009; Crossref-checked)","doi:10.1086/510463 (Temkin & Eldredge 2007; Crossref-checked)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7601-1 (Biologie grade 10, Entstehung der Artenvielfalt; read in the topic cache)","Sachsen Lehrplan topic lehrplan-522-1/lernbereich-7602-1 (Biologie grade 10, Stammesgeschichte des Menschen; read in the topic cache)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Common Ancestor","core_counterparts":[{"space":"bio","label":"Common Ancestor","relation":"broader"}],"reason":"The branch point of Descent: the source of later versions. Handled as part of Descent, which also covers languages and texts.","confidence":"medium"},{"core_concept":"Phylogeny","core_counterparts":[{"space":"bio","label":"Phylogeny","relation":"broader"}],"reason":"The tree-drawing side of Descent. Language trees, manuscript trees and artifact trees use the same method, so one general concept carries all of them.","confidence":"medium"}]}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b1acf54f-603b-53c6-ad57-3dbed700f74b', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Descent (biology)', 'Organisms descend from parents. Two lineages that split from a common ancestor share inherited features, and the pattern of splits is drawn as a phylogenetic tree. Population splits can end in separate species.', 'e0a89c95-8625-539f-93ef-ac864737144a', '{"level":"discipline-facet","facet_of":"Descent","definition":"Organisms descend from parents. Two lineages that split from a common ancestor share inherited features, and the pattern of splits is drawn as a phylogenetic tree. Population splits can end in separate species.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-descent-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('35ac72fb-387f-580f-b8f5-9596e2aa1820', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Descent (culture)', 'Languages and hand-copied texts descend from earlier ones. Shared words or shared copying errors show which versions are related, and trees are rebuilt with methods borrowed from biology. Borrowing and mixing between lines also happens.', 'e0a89c95-8625-539f-93ef-ac864737144a', '{"level":"discipline-facet","facet_of":"Descent","definition":"Languages and hand-copied texts descend from earlier ones. Shared words or shared copying errors show which versions are related, and trees are rebuilt with methods borrowed from biology. Borrowing and mixing between lines also happens.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-descent-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0a637904-6292-522b-b0d2-a4d11f34ca51', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Descent (technology)', 'Designs descend from earlier designs, with features carried forward across versions. Family trees of artifacts can be drawn, but makers often combine features from different lines, which makes the pattern more like a network.', 'e0a89c95-8625-539f-93ef-ac864737144a', '{"level":"discipline-facet","facet_of":"Descent","definition":"Designs descend from earlier designs, with features carried forward across versions. Family trees of artifacts can be drawn, but makers often combine features from different lines, which makes the pattern more like a network.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-descent-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Cooperation
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Parties act together so that each gains from the others'' actions, and some mechanism keeps the arrangement going when a party could gain by holding back. The mechanism differs by domain.","excludes":"Intention is needed in many human cases and absent in bees, cleaner fish and software. Hunting together is not always cooperation, because each animal may gain alone. Costly help to relatives counts only if gains to shared genes are included. Cooperation within a group can harm outsiders.","core_counterparts":[{"space":"soc","label":"Cooperation","relation":"broader"},{"space":"soc","label":"Collective Action","relation":"related"}],"curriculum_use":"Lets one concept describe packs (Klasse 5), bee colonies (Klasse 6), pollination and cleaner partnerships (Klasse 9), cooperatives and Bismarck''s alliances (Klasse 8), and team work in Informatik (Klassen 8, 10), each with its own sustaining mechanism.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-cooperation","ConceptBase OE-CONCEPT-openevo-design-concept-cooperation-games","TheoryBase OE-THEORY-core-design-principles-for-cooperation (author-draft status)","DOI 10.1111/j.1420-9101.2006.01258.x (West, Griffin & Gardner 2007, Crossref checked)","DOI 10.1126/science.1133755 (Nowak 2006, Crossref checked)","DOI 10.1126/science.7466396 (Axelrod & Hamilton 1981, Crossref checked)","DOI 10.1016/0022-5193(64)90038-4 (Hamilton 1964, Crossref checked)","DOI 10.1038/nature04755 (Bshary & Grutter 2006, cleaner fish, Crossref checked)","DOI 10.1038/nature01931 (Kiers et al. 2003, host sanctions, Crossref checked)","DOI 10.1046/j.1461-0248.2001.00218.x (Bronstein 2001, exploitation of mutualisms, Crossref checked)","DOI 10.1086/284844 (Packer & Ruttan 1988, cooperative hunting, Crossref checked)","DOI 10.1017/cbo9780511807763 (Ostrom 1990; LiteratureBase OE-LITERATURE-ostrom-1990)","DOI 10.1038/415137a (Fehr & Gächter 2002, Crossref checked)","unverified: Leibo et al. 2017, Multi-agent reinforcement learning in sequential social dilemmas (AAMAS)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Collective Action","core_counterparts":[{"space":"soc","label":"Collective Action","relation":"related"}],"reason":"Collective Action names the free-rider problem that Cooperation''s sustaining mechanisms answer. ConceptBase holds a general Social Dilemma sense, so it fits as domain meanings of Cooperation. Merge with Cooperation''s own facets.","confidence":"medium"}]}'::jsonb) WHERE id = 'c13c4fe4-a865-52b5-9203-154e5934dd92';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9eaf39b4-eda0-5acc-bd8c-7a1528dbf76a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cooperation (biology)', 'Animals or other organisms help or work with partners, and selection has favoured the helping. It is kept going by shared interest in the result, relatedness, repeated dealings, or partner choice and sanctions. Examples: cooperative breeding, cleaner fish, pollination partnerships.', 'c13c4fe4-a865-52b5-9203-154e5934dd92', '{"level":"discipline-facet","facet_of":"Cooperation","definition":"Animals or other organisms help or work with partners, and selection has favoured the helping. It is kept going by shared interest in the result, relatedness, repeated dealings, or partner choice and sanctions. Examples: cooperative breeding, cleaner fish, pollination partnerships.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cooperation-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4f700d52-8e6c-5b42-a2f5-4e4a01c1e840', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cooperation (culture)', 'People coordinate on a task or shared resource. Trust, norms, incentives, reputation or institutions keep members contributing when free riding would pay. Examples: a village water scheme, a cooperative, an alliance between states, a school project team.', 'c13c4fe4-a865-52b5-9203-154e5934dd92', '{"level":"discipline-facet","facet_of":"Cooperation","definition":"People coordinate on a task or shared resource. Trust, norms, incentives, reputation or institutions keep members contributing when free riding would pay. Examples: a village water scheme, a cooperative, an alliance between states, a school project team.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cooperation-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('06c3acf1-8499-5b35-8c2e-3d1ac06da461', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cooperation (AI and computation)', 'Programs or robots pursue a joint result. A shared reward or a common protocol keeps each one contributing, and the designer sets it. Agents with separate rewards can face a free-rider temptation. Example: robot teams.', 'c13c4fe4-a865-52b5-9203-154e5934dd92', '{"level":"discipline-facet","facet_of":"Cooperation","definition":"Programs or robots pursue a joint result. A shared reward or a common protocol keeps each one contributing, and the designer sets it. Agents with separate rewards can face a free-rider temptation. Example: robot teams.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cooperation-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Conflict
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Two or more parties whose pursuits cannot all succeed at once, because they draw on the same limited resource or have incompatible aims. Parties can be organisms, species, people, groups or programs.","excludes":"Competition between organisms needs no intention and can involve no contact. Predation and parasitism are one-sided and differ from competition. Persecution and bullying are one-sided harm, and calling them a clash of interests hides who acted. Software ''conflict'' is a clash of operations.","core_counterparts":[{"space":"soc","label":"Conflict","relation":"broader"},{"space":"bio","label":"Selection Pressure","relation":"related"}],"curriculum_use":"Describes ecological Konkurrenz (Klasse 9), territory and aggression in mammals (Klasse 5), and war and resistance topics (Klassen 8 to 10). The excludes line guards the persecution and bullying cases (Ethik Klasse 6) against a two-sided reading.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-conflict","ConceptBase NGSS competencies OE-COMPETENCY-000110 (MS-LS2-1) and OE-COMPETENCY-000148 (HS-LS4-2, competition for limited resources)","ConceptBase OE-SANDBOX-CONCEPT-000016 (Social Dilemma: distinguishes aligned, mixed and fully opposed interests)","LiteratureBase OE-LITERATURE-jessup-ode-balgopal-2016 (competition for limiting resources)","LiteratureBase OE-LITERATURE-schluter-2010 (resource competition in sticklebacks)","unverified: the computing facet rests on standard AI textbook material on zero-sum game search and on resource contention; no citation checked"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = 'bd8381b9-7a20-5940-b9ec-5b053c75ea8e';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('a0d25076-7bb1-5da1-97ac-465014025e02', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Conflict (biology)', 'Competition and fighting. Individuals or species use the same limited food, space or mates, so one party''s gain is another''s loss. It can be indirect, with no contact, or direct, as in threat display, fights and territory defence.', 'bd8381b9-7a20-5940-b9ec-5b053c75ea8e', '{"level":"discipline-facet","facet_of":"Conflict","definition":"Competition and fighting. Individuals or species use the same limited food, space or mates, so one party''s gain is another''s loss. It can be indirect, with no contact, or direct, as in threat display, fights and territory defence.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-conflict-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d8768502-6cee-5f63-bd0b-ea73d60a57a0', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Conflict (culture)', 'People or groups hold opposed interests, values or goals and act on them, from arguments and strikes to war. They can negotiate, appeal to rules or use force. Conflict can end in settlement, domination or a standoff.', 'bd8381b9-7a20-5940-b9ec-5b053c75ea8e', '{"level":"discipline-facet","facet_of":"Conflict","definition":"People or groups hold opposed interests, values or goals and act on them, from arguments and strikes to war. They can negotiate, appeal to rules or use force. Conflict can end in settlement, domination or a standoff.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-conflict-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f32257e5-deb6-5b7a-84af-cecf685b2a49', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Conflict (AI and computation)', 'Programs with opposed objectives, such as two game-playing agents where one''s win is the other''s loss. The designer builds the opposition into the objectives. The programs have no interests of their own.', 'bd8381b9-7a20-5940-b9ec-5b053c75ea8e', '{"level":"discipline-facet","facet_of":"Conflict","definition":"Programs with opposed objectives, such as two game-playing agents where one''s win is the other''s loss. The designer builds the opposition into the objectives. The programs have no interests of their own.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-conflict-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Culture
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Behaviours, knowledge, beliefs and artifacts that group members acquire from one another by social learning (watching, listening to or copying others), that are typical of the group, and that persist as individual members come and go.","excludes":"Animal traditions lack, as far as is known, symbols, enforced norms and steady cumulative gain. Cultural differences between peoples are learned and show nothing about genetic differences, although culture and genes can affect each other (dairy farming and milk digestion). A culture has no fixed trait list.","core_counterparts":[{"space":"soc","label":"Culture","relation":"broader"}],"curriculum_use":"Describes kulturelle Leistungen (China, Klasse 8) and citizenship education across eras (Klasse 6). Also gives a bounded way to place animal traditions as a contrast case to human culture.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-culture","ConceptBase OE-SANDBOX-CONCEPT-000019 (Cumulative Culture) and OE-SANDBOX-CONCEPT-000005 (Machine Culture)","DOI 10.1038/21415 (Whiten, Goodall, McGrew et al. 1999, Crossref checked)","DOI 10.1098/rstb.2006.1998 (Whiten & van Schaik 2007, Crossref checked)","DOI 10.1017/ehs.2019.1 (Schuppli & van Schaik 2019, Crossref checked)","DOI 10.1002/evan.10111 (Laland & Hoppitt 2003, Crossref checked)","DOI 10.1017/S0140525X0100396X (Rendell & Whitehead 2001, Crossref checked)","DOI 10.1098/rspb.2018.0712 (Mesoudi & Thornton 2018, Crossref checked)","DOI 10.1073/pnas.1203179109 (Riedl et al. 2012, no third-party punishment in chimpanzees, Crossref checked)","DOI 10.1038/s41562-023-01742-2 (Brinkmann et al. 2023, Crossref checked)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '8c0525a4-0873-52c6-a097-8915714a33ae';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0bb5f0d3-3ea4-58d8-99a3-e6e62ac9b14a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Culture (biology)', 'Group-typical behaviour that animals learn from others and pass on: chimpanzee tool use, regional bird dialects, humpback whale song. Documented in primates, birds, whales and fish. Cumulative build-up over generations is rare or debated.', '8c0525a4-0873-52c6-a097-8915714a33ae', '{"level":"discipline-facet","facet_of":"Culture","definition":"Group-typical behaviour that animals learn from others and pass on: chimpanzee tool use, regional bird dialects, humpback whale song. Documented in primates, birds, whales and fish. Cumulative build-up over generations is rare or debated.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-culture-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4ddaf1c1-9e90-5be1-b4a4-c13defc8b6ee', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Culture (culture)', 'Human culture adds language, symbols, shared norms and deliberate teaching. Knowledge, beliefs, practices and artifacts build up over generations, so a group holds more than any one member could invent alone (cumulative culture).', '8c0525a4-0873-52c6-a097-8915714a33ae', '{"level":"discipline-facet","facet_of":"Culture","definition":"Human culture adds language, symbols, shared norms and deliberate teaching. Knowledge, beliefs, practices and artifacts build up over generations, so a group holds more than any one member could invent alone (cumulative culture).","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-culture-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('05a0aefb-64cb-5a5a-97fc-b1051722100c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Culture (AI and computation)', 'Proposed extension. Systems trained on human cultural products carry patterns forward, and their outputs shape what people see and make next, which later systems learn from. Researchers call this machine culture. Whether machines learn socially is debated.', '8c0525a4-0873-52c6-a097-8915714a33ae', '{"level":"discipline-facet","facet_of":"Culture","definition":"Proposed extension. Systems trained on human cultural products carry patterns forward, and their outputs shape what people see and make next, which later systems learn from. Researchers call this machine culture. Whether machines learn socially is debated.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-culture-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Institutions
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Stable rules, written or unwritten, that a group recognises, together with the arrangements that apply them. They shape what members may, must or must not do and outlast any one member. This is mainly a human case.","excludes":"Law is a formal institution. Norms and conventions are the informal kind. Animal rank orders and policing belong under Group, Power and Cooperation, because no rule that members recognise is known. Software rules (protocols, permissions) cannot be broken, while laws and customs can, and people enforce them afterwards.","core_counterparts":[{"space":"soc","label":"Institutions","relation":"same"}],"curriculum_use":"Describes law and constitutions (Klassen 8 to 10), traffic rules (Klassen 1 to 2), market forms (Klasse 8), class rules (Klasse 5) and public facilities. Protocols and access rules in Informatik can be compared as built-in rules.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-institutions","ConceptBase OE-CONCEPT-openevo-design-concept-governing-the-commons","DOI 10.1017/CBO9780511808678 (North 1990, formal and informal rules, Crossref checked)","DOI 10.1017/cbo9780511807763 (Ostrom 1990; LiteratureBase OE-LITERATURE-ostrom-1990)","DOI 10.1038/nature04326 (Flack et al. 2006, policing in primates, Crossref checked)","DOI 10.1038/342796a0 (Ratnieks & Visscher 1989, worker policing, Crossref checked)","unverified: Lessig 1999, Code and Other Laws of Cyberspace (software as a regulator)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '4ebf512e-ba71-59c4-8e93-e03007a9d829';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1f5a13de-42a5-5229-ac22-0f3845e8fe75', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Institutions (culture)', 'Laws, constitutions, courts, schools, markets and customs. Formal institutions are written down and applied by officials. Informal ones are customs and conventions upheld by approval and disapproval (see Norms). People make, follow and change them.', '4ebf512e-ba71-59c4-8e93-e03007a9d829', '{"level":"discipline-facet","facet_of":"Institutions","definition":"Laws, constitutions, courts, schools, markets and customs. Formal institutions are written down and applied by officials. Informal ones are customs and conventions upheld by approval and disapproval (see Norms). People make, follow and change them.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-institutions-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Norms
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"A shared expectation within a group about how members should behave, upheld by the group''s own approval, disapproval or exclusion. No formal authority is needed. This is mainly a human case.","excludes":"Animal conformity is copying the majority, and no animal is known to expect that others ought to follow. Written law (Rechtsnorm) is an institution. A report of what a group expects differs from a claim that something ought to be done. Averages, Normwerte, DIN-Normen and the Reaktionsnorm are other senses.","core_counterparts":[{"space":"soc","label":"Norms","relation":"same"}],"curriculum_use":"Describes Netiquette and Umgangsformen, class and community rules, group pressure, and ethical demands of religions (Klassen 5 to 9). Separates these from descriptive versus normative statements in Biologie (Klassen 7 to 10).","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-norms","ConceptBase AI4K12 OE-COMPETENCY-000528 (AI systems and the norms of the groups they serve)","DOI 10.1017/CBO9780511616037 (Bicchieri 2005, Crossref checked)","DOI 10.1037/0022-3514.58.6.1015 (Cialdini, Reno & Kallgren 1990, Crossref checked)","DOI 10.1006/jtbi.2003.3104 (Gintis 2003, internalisation of norms, Crossref checked)","DOI 10.1017/S0140525X14001356 (Norenzayan et al. 2016, religion and prosociality, Crossref checked)","DOI 10.1038/nature04047 (Whiten et al. 2005, conformity in chimpanzees, Crossref checked)","DOI 10.1073/pnas.1203179109 (Riedl et al. 2012, Crossref checked)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = 'c529c772-66e2-5915-93f8-adedafc7732d';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ab4fbe74-9e68-51d4-95a3-eb04aad01bb7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Norms (culture)', 'Customs, manners, netiquette and religious duties, as held and upheld by a community. Members praise those who follow a norm and criticise or shun those who do not. Whether a norm is justified is an ethical question.', 'c529c772-66e2-5915-93f8-adedafc7732d', '{"level":"discipline-facet","facet_of":"Norms","definition":"Customs, manners, netiquette and religious duties, as held and upheld by a community. Members praise those who follow a norm and criticise or shun those who do not. Whether a norm is justified is an ethical question.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-norms-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bfa62613-83fe-5b6a-b133-cf8242be58ff', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Norms (cognition)', 'In a person''s mind, a rule of conduct taken on as one''s own. The person expects to feel guilt or shame for breaking it and may follow it with nobody watching. One account of why people follow norms unwatched.', 'c529c772-66e2-5915-93f8-adedafc7732d', '{"level":"discipline-facet","facet_of":"Norms","definition":"In a person''s mind, a rule of conduct taken on as one''s own. The person expects to feel guilt or shame for breaking it and may follow it with nobody watching. One account of why people follow norms unwatched.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-norms-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Collective Intelligence
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"A group''s combined output solves a problem or estimates a quantity better than a typical member could alone. How members'' contributions are combined decides whether the group does better, and some ways of combining make it worse.","excludes":"Groups are not automatically smarter: copying, shared bias and a loud leader can make a crowd worse than its members (information cascades). Bees and ants have no leader and no plan, while human groups can plan and talk.","core_counterparts":[{"space":"comp","label":"Distributed System","relation":"related"}],"curriculum_use":"Describes colony-level problem solving and Arbeitsteilung in bees (Klasse 6), peer-to-peer and collaboration services in networks (Klassen 8 and 9), and team projects in Informatik (Klasse 10).","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-collective-intelligence","ConceptBase OE-SANDBOX-CONCEPT-000008 (Decentralized Causal Reasoning)","LiteratureBase OE-LITERATURE-anwarzai-2026, OE-LITERATURE-falandays-2023, OE-LITERATURE-muthukrishna-2016","DOI 10.1126/science.1193147 (Woolley et al. 2010, Crossref checked)","DOI 10.1126/science.1210361 (Seeley et al. 2012, honeybee swarms, Crossref checked)","DOI 10.1073/pnas.1008636108 (Lorenz et al. 2011, Crossref checked)","DOI 10.1038/075450a0 (Galton 1907, Crossref checked)","DOI 10.1073/pnas.0403723101 (Hong & Page 2004, Crossref checked; its result is debated)","DOI 10.1098/rstb.2015.0192 (Muthukrishna & Henrich 2016, Crossref checked)","unverified: Dorigo & Stützle 2004, Ant Colony Optimization (MIT Press)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '4e4ec762-ee46-53d3-afe3-da41c3d3f6af';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8eecacca-c328-5449-9f75-56be97c6600c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Collective Intelligence (biology)', 'Animal groups reach good decisions or solutions through simple local interactions with no leader. Honeybee scouts compare nest sites and reach a quorum (enough scouts agree), and ant trails converge on short routes through pheromone reinforcement.', '4e4ec762-ee46-53d3-afe3-da41c3d3f6af', '{"level":"discipline-facet","facet_of":"Collective Intelligence","definition":"Animal groups reach good decisions or solutions through simple local interactions with no leader. Honeybee scouts compare nest sites and reach a quorum (enough scouts agree), and ant trails converge on short routes through pheromone reinforcement.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-collective-intelligence-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('a07fc454-41e4-5d87-9222-5242932b1280', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Collective Intelligence (culture)', 'People pool estimates, skills or knowledge: averaging many guesses, team problem solving, science built on many researchers. Larger, well-connected populations may invent more (the collective brain; debated). Independent estimates help, while copying each other can spoil the result.', '4e4ec762-ee46-53d3-afe3-da41c3d3f6af', '{"level":"discipline-facet","facet_of":"Collective Intelligence","definition":"People pool estimates, skills or knowledge: averaging many guesses, team problem solving, science built on many researchers. Larger, well-connected populations may invent more (the collective brain; debated). Independent estimates help, while copying each other can spoil the result.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-collective-intelligence-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('12378d51-cef9-5c69-829f-20043bc86b70', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Collective Intelligence (AI and computation)', 'Methods that combine many simple units: voting ensembles of models, ant-colony and swarm search. The designer writes the combining rule. Units need no understanding of the whole problem.', '4e4ec762-ee46-53d3-afe3-da41c3d3f6af', '{"level":"discipline-facet","facet_of":"Collective Intelligence","definition":"Methods that combine many simple units: voting ensembles of models, ant-colony and swarm search. The designer writes the combining rule. Units need no understanding of the whole problem.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-collective-intelligence-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Communication
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"A sender produces a signal, a receiver responds to it, and a code shared by both sides links the signal to the response. Whether anything is understood differs by domain.","excludes":"Meaning and intention are present in human language and may be absent in animal signals and machine messages. A cue is information that nobody sent. Delivering a message correctly differs from being understood. Signals are not always honest in any domain.","core_counterparts":[{"space":"soc","label":"Communication","relation":"broader"},{"space":"comp","label":"Information","relation":"related"},{"space":"comp","label":"Distributed System","relation":"related"}],"curriculum_use":"Describes bird song and the Sender-Empfänger-Modell (Klasse 5), bee communication (Klasse 6), media and propaganda, and network protocols and communication services (Informatik Klassen 8 and 9).","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-communication","DOI 10.1111/j.1420-9101.2007.01497.x (Scott-Phillips 2008, Defining biological communication, Crossref checked)","DOI 10.1002/j.1538-7305.1948.tb01338.x (Shannon 1948; LiteratureBase OE-LITERATURE-shannon-1948)","DOI 10.1017/S0140525X05000129 (Tomasello et al. 2005, shared intentions, Crossref checked)","unverified: Maynard Smith & Harper 2003, Animal Signals (Oxford University Press)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '301b8eed-edd6-5c71-91df-5219467c24fb';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bce30ef1-535b-5eed-8330-5f9762da3647', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Communication (biology)', 'A signal shaped by selection to change a receiver''s behaviour, and a response shaped to read it: bird song, alarm calls, the honeybee dance. A cue carries information without being sent. No meaning is needed.', '301b8eed-edd6-5c71-91df-5219467c24fb', '{"level":"discipline-facet","facet_of":"Communication","definition":"A signal shaped by selection to change a receiver''s behaviour, and a response shaped to read it: bird song, alarm calls, the honeybee dance. A cue carries information without being sent. No meaning is needed.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-communication-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4d4cc30f-93ef-5f01-8776-1f5be14b5f84', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Communication (culture)', 'People exchange meaning through language, writing, images and gestures. Speakers intend to be understood, read each other''s intentions and share conventions that can be learned and changed. Messages can mislead, and interpretation depends on context.', '301b8eed-edd6-5c71-91df-5219467c24fb', '{"level":"discipline-facet","facet_of":"Communication","definition":"People exchange meaning through language, writing, images and gestures. Speakers intend to be understood, read each other''s intentions and share conventions that can be learned and changed. Messages can mislead, and interpretation depends on context.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-communication-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('3207a747-2423-5114-b813-3da30c581058', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Communication (technology)', 'Devices exchange encoded messages over a channel under an agreed protocol, as in networks and telephony. The protocol fixes the format and the steps. A message can be delivered correctly with nobody understanding it, and noise can corrupt it.', '301b8eed-edd6-5c71-91df-5219467c24fb', '{"level":"discipline-facet","facet_of":"Communication","definition":"Devices exchange encoded messages over a channel under an agreed protocol, as in networks and telephony. The protocol fixes the format and the steps. A message can be delivered correctly with nobody understanding it, and noise can corrupt it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-communication-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Group
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('7af8496b-4e17-56f0-97a0-bbfb9a109195', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Group', 'A set of individuals who interact with one another more than with outsiders, or who are treated as belonging together, so that membership affects who helps, shares with, competes with or excludes whom.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"definition":"A set of individuals who interact with one another more than with outsiders, or who are treated as belonging together, so that membership affects who helps, shares with, competes with or excludes whom.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-group","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Animal groups can carry markers such as colony smell. Belonging needs no shared identity. A bee colony has no ruler: the queen lays eggs and does not command. In animals, a population or a chance crowd is a group only if members interact. Human groups can rest on identity alone.","core_counterparts":[{"space":"soc","label":"Group","relation":"broader"},{"space":"bio","label":"Population","relation":"related"}],"curriculum_use":"Describes the bee colony as sozialer Verband (Klasse 6), packs and herds (Klasse 5), and parties, interest groups and nationalist movements (Klassen 8 and 9) with one concept and stated differences.","grounding":["DOI 10.1146/annurev.es.05.110174.001545 (Alexander 1974, evolution of social behaviour, Crossref checked)","DOI 10.1038/nature08366 (Clutton-Brock 2009, Crossref checked)","DOI 10.1002/ejsp.2420010202 (Tajfel et al. 1971, social categorization, Crossref checked)","DOI 10.1126/science.1210361 (Seeley et al. 2012, colony decisions without a ruler, Crossref checked)","ConceptBase OE-COMPETENCY-000141 (NGSS HS-LS2-8, group behavior)","ConceptBase OE-SANDBOX-CONCEPT-000021 (Ultrasociality)","TheoryBase OE-THEORY-symbolic-group-marking (author-draft status)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c7e2600e-ab91-5a87-b992-f74dc38b0398', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Group (biology)', 'Animals that stay together and interact repeatedly (sozialer Verband): packs, troops, insect colonies. Members may know one another as individuals, and insects use colony smell. Group life brings gains such as defence and costs such as competition.', '7af8496b-4e17-56f0-97a0-bbfb9a109195', '{"level":"discipline-facet","facet_of":"Group","definition":"Animals that stay together and interact repeatedly (sozialer Verband): packs, troops, insect colonies. Members may know one another as individuals, and insects use colony smell. Group life brings gains such as defence and costs such as competition.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-group-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('75d2faa3-b4f6-5f87-9762-b0cd17a0fbc6', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Group (culture)', 'People who see themselves, or are seen by others, as one body with shared interests or identity: families, school classes, parties, nations. Members need not meet. Membership can be chosen, inherited, or assigned by outsiders, sometimes against a person''s will.', '7af8496b-4e17-56f0-97a0-bbfb9a109195', '{"level":"discipline-facet","facet_of":"Group","definition":"People who see themselves, or are seen by others, as one body with shared interests or identity: families, school classes, parties, nations. Members need not meet. Membership can be chosen, inherited, or assigned by outsiders, sometimes against a person''s will.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-group-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Role
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('08754b6f-b706-5915-a2c2-045d8aa65a93', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Role', 'A recurring position in a group''s division of labour, with typical behaviour attached. Who fills it, and whether they can change position, differs by domain.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"definition":"A recurring position in a group''s division of labour, with typical behaviour attached. Who fills it, and whether they can change position, differs by domain.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-role","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Insect individuals do not accept or refuse a role. Human roles carry expectations and sanctions and can be negotiated. ''Caste'' also names a hereditary human social class, a different thing. Software roles carry no expectations or feelings.","core_counterparts":[{"space":"soc","label":"Role","relation":"broader"},{"space":"comp","label":"Distributed System","relation":"related"}],"curriculum_use":"Describes Arbeitsteilung in bees (Klasse 6), roles in groups and society (Ethik and Gemeinschaftskunde), and client-server versus peer-to-peer roles in Informatik (Klasse 9).","grounding":["DOI 10.1146/annurev.so.12.080186.000435 (Biddle 1986, role theory, Crossref checked)","DOI 10.1146/annurev.en.37.010192.003225 (Robinson 1992, division of labour in insects, Crossref checked)","DOI 10.1146/annurev.ento.46.1.413 (Beshers & Fewell 2001, Crossref checked)","DOI 10.1038/nature08366 (Clutton-Brock 2009, helpers, Crossref checked)","DOI 10.1109/2.485845 (Sandhu et al. 1996, role-based access control, Crossref checked)","DOI 10.1023/A:1010071910869 (Wooldridge, Jennings & Kinny 2000, roles for software agents, Crossref checked)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('aaed63ec-24a9-579f-946d-df5c2cb89c12', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Role (biology)', 'Social insect castes and age-linked tasks, and helpers in cooperative breeders. In honeybees, workers shift from nursing to foraging as they age. Roles arise from development or age, and a caste can be fixed for life.', '08754b6f-b706-5915-a2c2-045d8aa65a93', '{"level":"discipline-facet","facet_of":"Role","definition":"Social insect castes and age-linked tasks, and helpers in cooperative breeders. In honeybees, workers shift from nursing to foraging as they age. Roles arise from development or age, and a caste can be fixed for life.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-role-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c2eb9835-54d3-5b6f-8cd7-2af3baa893e3', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Role (culture)', 'A position such as teacher, parent, judge or citizen. Other people expect certain behaviour from whoever holds it, and sanction departures. People are assigned, choose, train for or inherit roles, and can hold several at once.', '08754b6f-b706-5915-a2c2-045d8aa65a93', '{"level":"discipline-facet","facet_of":"Role","definition":"A position such as teacher, parent, judge or citizen. Other people expect certain behaviour from whoever holds it, and sanction departures. People are assigned, choose, train for or inherit roles, and can hold several at once.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-role-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('a491c05d-fbe7-5869-bd01-12a137426f72', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Role (AI and computation)', 'Named positions in a system: client and server in a network, administrator and user in an access scheme. The role fixes what its holder may do, and any machine or account can hold it.', '08754b6f-b706-5915-a2c2-045d8aa65a93', '{"level":"discipline-facet","facet_of":"Role","definition":"Named positions in a system: client and server in a network, administrator and user in an access scheme. The role fixes what its holder may do, and any machine or account can hold it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-role-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Incentive
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d74633cc-737d-5760-9c98-28c9381c401f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Incentive', 'A benefit or cost attached to an option that changes how often the option is chosen. How the effect arises differs by domain: through expectation and judgement, through learning, or through an update rule.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"definition":"A benefit or cost attached to an option that changes how often the option is chosen. How the effect arises differs by domain: through expectation and judgement, through learning, or through an update rule.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-incentive","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"People can offer and understand an incentive. Animals and learning programs respond to payoffs without understanding them. Payoffs in evolution change which strategies persist across generations, which is selection. They do not change one individual''s choice. Money is one kind of incentive. Approval and fairness also move people.","core_counterparts":[{"space":"soc","label":"Incentive","relation":"broader"},{"space":"comp","label":"Machine Learning","relation":"related"}],"curriculum_use":"Describes market coordination through prices, supply and demand (Gemeinschaftskunde Klassen 8 and 10), reward-based learning in AI units, and foraging choices in animal behaviour.","grounding":["ConceptBase OE-SANDBOX-CONCEPT-000023 (Homo Economicus: material incentives can backfire)","ConceptBase AI4K12 OE-COMPETENCY-000399 (reinforcement learning) and OE-COMPETENCY-000341 (maximizing reward)","DOI 10.1086/468061 (Gneezy & Rustichini 2000, A fine is a price, Crossref checked)","DOI 10.1037/0033-2909.125.6.627 (Deci, Koestner & Ryan 1999, Crossref checked)","DOI 10.1111/1467-6419.00150 (Frey & Jegen 2001, Crossref checked)","DOI 10.1016/0040-5809(76)90040-X (Charnov 1976, marginal value theorem, Crossref checked)","unverified: Amodei et al. 2016, Concrete problems in AI safety (reward misspecification)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ccef39a3-7cae-5a31-b11e-0a177ddc4c0e', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Incentive (culture)', 'Prices, wages, grades, fines, praise and taxes. People weigh expected gains and costs, along with fairness, reputation and values. Material incentives can backfire: a fine for lateness can make lateness more common if it turns a duty into a price.', 'd74633cc-737d-5760-9c98-28c9381c401f', '{"level":"discipline-facet","facet_of":"Incentive","definition":"Prices, wages, grades, fines, praise and taxes. People weigh expected gains and costs, along with fairness, reputation and values. Material incentives can backfire: a fine for lateness can make lateness more common if it turns a duty into a price.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-incentive-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b5d7f62f-6943-56c0-9f7b-3a481be0d3de', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Incentive (biology)', 'Animals shift their choices toward options with higher payoffs: foraging animals leave a patch when the gain rate falls, and rewarded actions are repeated (reinforcement). Evolution shapes which payoffs matter. The animal needs no idea of why.', 'd74633cc-737d-5760-9c98-28c9381c401f', '{"level":"discipline-facet","facet_of":"Incentive","definition":"Animals shift their choices toward options with higher payoffs: foraging animals leave a patch when the gain rate falls, and rewarded actions are repeated (reinforcement). Evolution shapes which payoffs matter. The animal needs no idea of why.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-incentive-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4a8975a2-2de2-5eb4-9499-788b62677ff7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Incentive (AI and computation)', 'A reward signal returned after an action. A learning program changes its behaviour to collect more reward. People set the reward, so a badly chosen reward is followed faithfully, including in unintended ways.', 'd74633cc-737d-5760-9c98-28c9381c401f', '{"level":"discipline-facet","facet_of":"Incentive","definition":"A reward signal returned after an action. A learning program changes its behaviour to collect more reward. People set the reward, so a badly chosen reward is followed faithfully, including in unintended ways.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-incentive-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Power
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1864411a-7744-5150-8b9c-09a8e6f007c0', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Power', 'The ability of one party to affect another party''s options or outcomes, for example by controlling something the other needs, by force, or by shaping what the other believes. The ability belongs to the relationship between the parties.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"definition":"The ability of one party to affect another party''s options or outcomes, for example by controlling something the other needs, by force, or by shaping what the other believes. The ability belongs to the relationship between the parties.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-power","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Legitimacy, authority and law belong to human cases. Animal dominance does not rest on any rule that members accept. In wild wolf packs the ''alpha'' pair are the parents, so rank follows family position. Animal rank orders give no reason for human hierarchies. Shaping beliefs is mainly a human case.","core_counterparts":[{"space":"soc","label":"Power","relation":"broader"}],"curriculum_use":"Describes Rangordnung in mammals (Klasse 5), media manipulation (Ethik Klasse 7), colonial influence on borders and oil as an economic and political factor (Geographie Klasse 7), with the animal reading''s limits stated.","grounding":["DOI 10.1002/bs.3830020303 (Dahl 1957, The concept of power, Crossref checked)","DOI 10.1163/156853993X00290 (Drews 1993, dominance in animal behaviour, Crossref checked)","DOI 10.1139/z99-099 (Mech 1999, alpha status in wolf packs, Crossref checked)","DOI 10.1016/S1090-5138(00)00071-4 (Henrich & Gil-White 2001, prestige, Crossref checked)","DOI 10.1037/0033-295X.110.2.265 (Keltner, Gruenfeld & Anderson 2003, Crossref checked)","ConceptBase OE-SANDBOX-CONCEPT-000022 (Egalitarianism: leveling mechanisms against dominance)","LiteratureBase OE-LITERATURE-turchin-gavrilets-2009"],"confidence":"low","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('081fbdc2-6cf0-58fb-a24c-43ac63b8a92a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Power (biology)', 'Dominance: in a pair, one animal reliably gets first access to food, mates or space, because of past contest wins, size, age or inherited rank, and a threat now suffices. Ranks form an order in the group (Rangordnung).', '1864411a-7744-5150-8b9c-09a8e6f007c0', '{"level":"discipline-facet","facet_of":"Power","definition":"Dominance: in a pair, one animal reliably gets first access to food, mates or space, because of past contest wins, size, age or inherited rank, and a threat now suffices. Ranks form an order in the group (Rangordnung).","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-power-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8a773870-d0ba-5f5e-9a10-7674ea65d55d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Power (culture)', 'People hold power through force, control of money or resources, authority accepted as rightful, or influence over what others know and believe. Rulers, employers, owners, media and states all have it. Power can be limited by law, institutions and resistance.', '1864411a-7744-5150-8b9c-09a8e6f007c0', '{"level":"discipline-facet","facet_of":"Power","definition":"People hold power through force, control of money or resources, authority accepted as rightful, or influence over what others know and believe. Rulers, employers, owners, media and states all have it. Power can be limited by law, institutions and resistance.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-power-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Diffusion
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('82f88ea7-c641-579f-a698-5a417581d51c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Diffusion', 'Something spreads through a population because holders pass it to others they are in contact with. The pattern of spread depends on who is in contact with whom and on what makes a contact pass it on.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"definition":"Something spreads through a population because holders pass it to others they are in contact with. The pattern of spread depends on who is in contact with whom and on what makes a contact pass it on.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-diffusion","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Wide spread does not show that the thing is better or fitter. Spread can follow popularity, prestige or chance. One hand-over is Transmission, and Diffusion is the pattern across a population. Selection needs a reason some variants spread more, such as fit to the setting. Diffusion needs only contact.","core_counterparts":[{"space":"soc","label":"Diffusion","relation":"broader"}],"curriculum_use":"Describes the spread of industrialisation from England (Geschichte Klasse 8), of customs between communities, of infections between hosts, and of data across networks in Informatik.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-transmission","DOI 10.1086/226707 (Granovetter 1978, threshold models, Crossref checked)","DOI 10.1073/pnas.082090499 (Watts 2002, cascades on networks, Crossref checked)","DOI 10.1287/mnsc.15.5.215 (Bass 1969, product growth model, Crossref checked)","DOI 10.1038/nature13998 (Aplin et al., wild birds, Crossref checked)","DOI 10.1126/science.1231976 (Allen et al. 2013, humpback whales, Crossref checked)","LiteratureBase OE-LITERATURE-kendal-etal-2018-social-learning-strategies","unverified: Rogers, Diffusion of Innovations (5th edition, 2003)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('3034cbc6-6d31-56a6-aa66-f677097e251a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Diffusion (biology)', 'A pathogen passing between hosts, or a learned behaviour spreading along an animal group''s social ties, such as a new foraging trick in wild birds or lobtail feeding in humpback whales. Infection needs no choice by the host.', '82f88ea7-c641-579f-a698-5a417581d51c', '{"level":"discipline-facet","facet_of":"Diffusion","definition":"A pathogen passing between hosts, or a learned behaviour spreading along an animal group''s social ties, such as a new foraging trick in wild birds or lobtail feeding in humpback whales. Infection needs no choice by the host.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-diffusion-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('58560bfa-10a3-55ea-b784-4c43aa5472ca', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Diffusion (culture)', 'An idea, practice or technology spreads as people see it, hear of it and adopt it. Adoption often follows an S-shaped curve, with early adopters first. People adopt for many reasons: benefit, prestige, pressure or chance.', '82f88ea7-c641-579f-a698-5a417581d51c', '{"level":"discipline-facet","facet_of":"Diffusion","definition":"An idea, practice or technology spreads as people see it, hear of it and adopt it. Adoption often follows an S-shaped curve, with early adopters first. People adopt for many reasons: benefit, prestige, pressure or chance.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-diffusion-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d9f4e4de-1a94-585a-9c77-1cac9715b6ed', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Diffusion (AI and computation)', 'A file, message or program copy spreads over a network, or a node adopts a state when enough neighbours have. Simple rules on a contact network can reproduce epidemics and viral posts. A designer writes the passing-on rule.', '82f88ea7-c641-579f-a698-5a417581d51c', '{"level":"discipline-facet","facet_of":"Diffusion","definition":"A file, message or program copy spreads over a network, or a node adopts a state when enough neighbours have. Simple rules on a contact network can reproduce epidemics and viral posts. A designer writes the passing-on rule.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-diffusion-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Knowledge
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Information that a holder has kept, has grounds to rely on and can use to act or to answer questions. The holders are people and groups. The kind of grounds differs by domain.","excludes":"Information in genes, a library or a model''s weights is knowledge only when a holder can use it and has grounds to rely on it. Genes and immune memory were shaped by selection, and no holder checked them. A group can share a mistake, so agreement alone is not enough.","core_counterparts":[{"space":"soc","label":"Knowledge","relation":"broader"}],"curriculum_use":"Describes knowledge in history source work (limits of interpreting sources), curriculum goals about what students should know, and school topics on memory. Gives knowledge-base topics in informatics a flagged technical reading.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-knowledge","ConceptBase AI4K12 OE-COMPETENCY-000263 (what an agent must know)","DOI 10.1207/s15430421tip4104_2 (Krathwohl 2002, knowledge dimension, Crossref checked)","DOI 10.1145/3447772 (Hogan et al. 2021, Knowledge Graphs, Crossref checked)","DOI 10.1098/rstb.2015.0192 (Muthukrishna & Henrich 2016, Crossref checked)","TheoryBase OE-ASSUMPTION-factual-recall-adequate-proxy","DOI 10.1093/analys/23.6.121 (Gettier 1963, Crossref verified; background on justification)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = 'b9faf219-7d7f-5791-abca-c738d6130497';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0b9ed327-15d2-5f87-9fa0-1f7a6a8872f0', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Knowledge (cognition)', 'What a person has learned and keeps, including facts, concepts and know-how. It guides action and reasoning. People can often give reasons, and know-how is backed by a track record even when they cannot.', 'b9faf219-7d7f-5791-abca-c738d6130497', '{"level":"discipline-facet","facet_of":"Knowledge","definition":"What a person has learned and keeps, including facts, concepts and know-how. It guides action and reasoning. People can often give reasons, and know-how is backed by a track record even when they cannot.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-knowledge-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('444e7a88-4359-515a-a009-1a8b28be0aa7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Knowledge (culture)', 'Understanding a group holds and justifies together through shared records, expertise and checks such as evidence, peer review and source criticism. No member holds all of it. It outlasts its members when written down or taught.', 'b9faf219-7d7f-5791-abca-c738d6130497', '{"level":"discipline-facet","facet_of":"Knowledge","definition":"Understanding a group holds and justifies together through shared records, expertise and checks such as evidence, peer review and source criticism. No member holds all of it. It outlasts its members when written down or taught.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-knowledge-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('12536aa0-2195-5b83-8ce9-553336526128', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Knowledge (education)', 'The facts, concepts and procedures a curriculum selects for learners, which teaching tries to turn into understanding the learner can use. Knowing facts differs from applying them, so curricula also name skills and competences.', 'b9faf219-7d7f-5791-abca-c738d6130497', '{"level":"discipline-facet","facet_of":"Knowledge","definition":"The facts, concepts and procedures a curriculum selects for learners, which teaching tries to turn into understanding the learner can use. Knowing facts differs from applying them, so curricula also name skills and competences.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-knowledge-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0d638ab7-b214-542f-9ec9-7922ecc35d5d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Knowledge (AI and computation)', 'Technical reading: a knowledge base stores statements that a program searches to answer questions. People wrote or checked them and quality varies. The program has no grounds of its own. Whether a trained model''s patterns count is debated.', 'b9faf219-7d7f-5791-abca-c738d6130497', '{"level":"discipline-facet","facet_of":"Knowledge","definition":"Technical reading: a knowledge base stores statements that a program searches to answer questions. People wrote or checked them and quality varies. The program has no grounds of its own. Whether a trained model''s patterns count is debated.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-knowledge-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Information
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"A pattern that varies in step with something else. A receiver that can use that link becomes less uncertain about the other thing, or can act on it. Receivers include cells, animals, people and machines.","excludes":"Bits measure information only where the possible messages and their odds are known. Meaning and truth play no part in the bit count, yet both matter in human communication. Animal tracks and tree rings carry information although nobody meant to send it. Uncertainty here counts possibilities for any receiver.","core_counterparts":[{"space":"comp","label":"Information","relation":"broader"},{"space":"soc","label":"Communication","relation":"related"},{"space":"bio","label":"Inheritance","relation":"related"},{"space":"bio","label":"Gene","relation":"related"}],"curriculum_use":"Describes the Sachsen biology organizing field ''Information'' (senses, hormones, genes, brain memory), informatics ''Informationen und Daten'' with bits and units, and the source-checking topics in media, history and geography.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-information","TheoryBase OE-CROSSDOMAINCONSTRUCT-information-processing-domain-general","TheoryBase OE-CURRICULUMDECISION-bio-core-strand-101-no-information-concept","ConceptBase OE-COMPETENCY-000108 (NGSS MS-LS1-8, sensory receptors and memory)","DOI 10.1002/j.1538-7305.1948.tb01338.x (Shannon 1948, Crossref verified)","DOI 10.1086/392768 (Maynard Smith 2000, Crossref verified)","DOI 10.1086/392760 (Godfrey-Smith 2000, Crossref verified)","DOI 10.1086/344621 (Jablonka 2002, Crossref verified)","DOI 10.1007/s10539-006-9046-6 (Shea 2007, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Gene","core_counterparts":[{"space":"bio","label":"Gene","relation":"related"}],"reason":"The general idea a gene carries is stored information that is copied and read out. Information already names genetic encoding, so a biology facet there is enough. Gene itself stays a biology-only term.","confidence":"medium"}]}'::jsonb) WHERE id = '6c5398e6-801c-55f9-9732-a018ba999e6b';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e4424b3a-e861-5a7d-9c65-9d57c4475949', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Information (biology)', 'Pattern: a gene''s base sequence, a hormone level or an animal signal. Receiver: the cell''s machinery, an organ or another animal. Accounts differ on whether genes carry meaning or only cause effects. School biology rarely measures it in bits.', '6c5398e6-801c-55f9-9732-a018ba999e6b', '{"level":"discipline-facet","facet_of":"Information","definition":"Pattern: a gene''s base sequence, a hormone level or an animal signal. Receiver: the cell''s machinery, an organ or another animal. Accounts differ on whether genes carry meaning or only cause effects. School biology rarely measures it in bits.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-information-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d1c3d439-82e0-58f8-a108-97b460a4cbb7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Information (cognition)', 'Pattern: sensory input or a stored trace. Receiver: a nervous system whose later expectations and actions change. Memory is partly rebuilt at each recall, so a stored trace is not a copy of the input.', '6c5398e6-801c-55f9-9732-a018ba999e6b', '{"level":"discipline-facet","facet_of":"Information","definition":"Pattern: sensory input or a stored trace. Receiver: a nervous system whose later expectations and actions change. Memory is partly rebuilt at each recall, so a stored trace is not a copy of the input.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-information-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6eeb311d-aa1d-54f7-9fb7-af1f3141ad0a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Information (culture)', 'Pattern: words, pictures, records or media. Receiver: a person who reads them with shared codes. Meaning and truth matter here, so a message can mislead and its source needs checking.', '6c5398e6-801c-55f9-9732-a018ba999e6b', '{"level":"discipline-facet","facet_of":"Information","definition":"Pattern: words, pictures, records or media. Receiver: a person who reads them with shared codes. Meaning and truth matter here, so a message can mislead and its source needs checking.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-information-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('91348a61-708a-5996-8923-7a0be5773d11', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Information (AI and computation)', 'Pattern: a message chosen from a known set of possible messages. Receiver: a decoder built around the odds of each message. The less likely the message, the more bits it carries. Meaning plays no part.', '6c5398e6-801c-55f9-9732-a018ba999e6b', '{"level":"discipline-facet","facet_of":"Information","definition":"Pattern: a message chosen from a known set of possible messages. Receiver: a decoder built around the odds of each message. The less likely the message, the more bits it carries. Meaning plays no part.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-information-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Representation
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Something that stands in for something else, so that people can think about, talk about or act on the second thing through the first, and programs can process it. What makes it a stand-in differs by domain: shared structure, agreed conventions or learning history.","excludes":"A shared or computed stand-in works only for a user who treats it as one, so the same marks can stand for different things. Brains use mental representations without anyone treating them as stand-ins. A map is not the territory; a stored vector means nothing to the program alone.","core_counterparts":[{"space":"comp","label":"Representation","relation":"broader"},{"space":"comp","label":"Data","relation":"broader"},{"space":"comp","label":"Model","relation":"broader"}],"curriculum_use":"Describes map work in geography and Sachunterricht (the map as a generalized picture), number systems, markup languages and binary coding in informatics, and mental images or concepts in cognition topics.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-representation","ConceptBase OE-COMPETENCY-000283 (AI4K12: the map is not the territory)","TheoryBase OE-THEORY-restructuration-theory","LiteratureBase OE-LITERATURE-wilensky-papert-2010","DOI 10.1007/s10539-006-9046-6 (Shea 2007, Crossref verified; representation in inheritance systems, background only)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Data","core_counterparts":[{"space":"comp","label":"Data","relation":"broader"}],"reason":"Data is a recorded kind of representation. Every Sachsen case tagged for it fits the narrow sense, so a separate general entry adds a word and no new structure.","confidence":"medium"}]}'::jsonb) WHERE id = 'fe387dcf-751c-59e6-9fa2-8fcc6abecea3';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e72250d5-ffb0-5cd9-b7f8-ce4746da96b7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Representation (cognition)', 'Mental structures such as images, concepts and schemas that stand for things and let a person reason about them when they are absent. They are largely built from experience and can be partial or wrong.', 'fe387dcf-751c-59e6-9fa2-8fcc6abecea3', '{"level":"discipline-facet","facet_of":"Representation","definition":"Mental structures such as images, concepts and schemas that stand for things and let a person reason about them when they are absent. They are largely built from experience and can be partial or wrong.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-representation-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('7b7d876a-dd57-5846-b3f0-88c540484351', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Representation (culture)', 'Shared sign systems such as words, writing, numerals, maps and diagrams. A community agrees what the signs stand for, and the choice of system changes what is easy to say, calculate or notice.', 'fe387dcf-751c-59e6-9fa2-8fcc6abecea3', '{"level":"discipline-facet","facet_of":"Representation","definition":"Shared sign systems such as words, writing, numerals, maps and diagrams. A community agrees what the signs stand for, and the choice of system changes what is easy to say, calculate or notice.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-representation-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d9d4bc73-d287-5e6f-9974-aa6f15e0bda8', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Representation (education)', 'Maps, diagrams, tables and models used to teach. Learners must learn the conventions and see that a map is a simplified stand-in for a place. Reading and making representations is taught as a skill.', 'fe387dcf-751c-59e6-9fa2-8fcc6abecea3', '{"level":"discipline-facet","facet_of":"Representation","definition":"Maps, diagrams, tables and models used to teach. Learners must learn the conventions and see that a map is a simplified stand-in for a place. Reading and making representations is taught as a skill.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-representation-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bed2b060-0aa3-5f86-8897-0ce11420f3fb', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Representation (AI and computation)', 'Technical reading: tables, code, vectors and recorded values (data) that a program stores and processes as standing for something. Data become information only for a receiver who can read them. People supply the meaning.', 'fe387dcf-751c-59e6-9fa2-8fcc6abecea3', '{"level":"discipline-facet","facet_of":"Representation","definition":"Technical reading: tables, code, vectors and recorded values (data) that a program stores and processes as standing for something. Data become information only for a receiver who can read them. People supply the meaning.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-representation-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Learning
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"A lasting change in how an individual or system acts or responds, brought about by experience. Experience may be direct, observed in others or arranged by a teacher or designer.","excludes":"In machine learning what changes is a set of numbers, and no understanding is implied. Many trained models stay fixed until retrained. Evolution changes populations over generations, while learning changes one individual; some theories link the two as selection. Fatigue or injury can change behavior without learning.","core_counterparts":[{"space":"comp","label":"Machine Learning","relation":"broader"}],"curriculum_use":"Describes learning in Sachunterricht (learning from mistakes, learning together), human and animal learned behavior in biology, and machine learning in informatics grade 9 under a flagged technical reading.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-learning","ConceptBase OE-COMPETENCY-000358 (AI4K12 3-5: people and computers both learn from patterns, people are flexible)","ConceptBase OE-COMPETENCY-000360 (AI4K12 6-8: human learning versus machine learning)","ConceptBase OE-COMPETENCY-000394 (AI4K12 9-12: algorithms adjust internal representations)","TheoryBase OE-THEORY-sociocultural-progression-as-community-practice","DOI 10.1147/rd.33.0210 (Samuel 1959, Crossref verified)","TheoryBase OE-CROSSDOMAINCONSTRUCT-selection-as-hierarchical-bayesian-updating (theory bridge: the record treats learning and evolution as one kind of updating at different grains and does not claim they are identical)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Machine Learning","core_counterparts":[{"space":"comp","label":"Machine Learning","relation":"broader"}],"reason":"Machine Learning shares the word with Learning and differs in what changes. It fits better as one flagged technical facet of Learning than as a second general concept.","confidence":"high"}]}'::jsonb) WHERE id = '241ac4b1-00b3-517c-b3b5-10029f1efdc6';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d5ae2237-2d38-55e3-83fc-6be62b370048', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Learning (cognition)', 'A person changes what they know, expect or can do because of experience. The change is stored in the nervous system, lasts, and shapes later action. It can be accurate or wrong, and it includes learning from other people.', '241ac4b1-00b3-517c-b3b5-10029f1efdc6', '{"level":"discipline-facet","facet_of":"Learning","definition":"A person changes what they know, expect or can do because of experience. The change is stored in the nervous system, lasts, and shapes later action. It can be accurate or wrong, and it includes learning from other people.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-learning-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('29b74d12-3e3e-59ea-b43d-e51936b61bfd', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Learning (biology)', 'Many animals change behavior through experience: habituation, association, trial and error and copying others. The change happens within one lifetime and, in nervous systems, rests on altered connections between nerve cells. Change across generations by selection is a separate process.', '241ac4b1-00b3-517c-b3b5-10029f1efdc6', '{"level":"discipline-facet","facet_of":"Learning","definition":"Many animals change behavior through experience: habituation, association, trial and error and copying others. The change happens within one lifetime and, in nervous systems, rests on altered connections between nerve cells. Change across generations by selection is a separate process.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-learning-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2ead6099-f55f-5895-8783-54f4018b2e91', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Learning (culture)', 'Newcomers take on a group''s norms, roles and knowledge by taking part in its activities and being instructed. The change is described as growing participation. What changes is a person''s skill and place in the group.', '241ac4b1-00b3-517c-b3b5-10029f1efdc6', '{"level":"discipline-facet","facet_of":"Learning","definition":"Newcomers take on a group''s norms, roles and knowledge by taking part in its activities and being instructed. The change is described as growing participation. What changes is a person''s skill and place in the group.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-learning-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('95243b6f-035f-5bbf-81c0-3f5b7246bfb6', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Learning (education)', 'A learner meets planned experiences, and the change is judged against stated goals. Prior ideas shape what is learned. The result can be new knowledge, a skill or a revised belief, and it can fade without practice.', '241ac4b1-00b3-517c-b3b5-10029f1efdc6', '{"level":"discipline-facet","facet_of":"Learning","definition":"A learner meets planned experiences, and the change is judged against stated goals. Prior ideas shape what is learned. The result can be new knowledge, a skill or a revised belief, and it can fade without practice.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-learning-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d04fc003-796a-50f7-9274-dcf954529881', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Learning (AI and computation)', 'Technical reading: a procedure adjusts a model''s numbers from example data or trial outcomes so that a designer-chosen score improves. Supervised, unsupervised and reinforcement methods differ in their feedback. No understanding is implied.', '241ac4b1-00b3-517c-b3b5-10029f1efdc6', '{"level":"discipline-facet","facet_of":"Learning","definition":"Technical reading: a procedure adjusts a model''s numbers from example data or trial outcomes so that a designer-chosen score improves. Supervised, unsupervised and reinforcement methods differ in their feedback. No understanding is implied.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-learning-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Teaching
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Behavior by one individual or system that responds to another''s learning needs and helps that other acquire a skill or piece of knowledge sooner or more reliably than it would alone.","excludes":"Intention to teach is part of human teaching. Animal studies test only the behavior pattern and its cost to the teacher. Setting an example without regard to who is watching is modeling. Tutoring software has no intent. Learners can learn with no teacher present.","core_counterparts":[],"curriculum_use":"Describes teaching in school topics such as learning together in Sachunterricht, and lets the biology grade 10 topic on learned behavior separate teaching from learning alone.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-teaching","DOI 10.1086/417553 (Caro and Hauser 1992, Crossref verified)","DOI 10.1126/science.1128727 (Thornton and McAuliffe 2006, Crossref verified)","DOI 10.1016/j.tics.2009.01.005 (Csibra and Gergely 2009, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = 'b0040254-6692-5ff3-8c4a-41b7a0bd1e51';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f4f13e9a-896b-510c-9058-42baac9f6c3c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Teaching (biology)', 'Meerkat adults give pups prey in forms matched to the pups'' age, which improves the pups'' skill. Researchers test the behavior pattern and its cost to the adult. They do not need to know whether the adult intends to teach.', 'b0040254-6692-5ff3-8c4a-41b7a0bd1e51', '{"level":"discipline-facet","facet_of":"Teaching","definition":"Meerkat adults give pups prey in forms matched to the pups'' age, which improves the pups'' skill. Researchers test the behavior pattern and its cost to the adult. They do not need to know whether the adult intends to teach.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-teaching-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9eef818c-5bec-5556-9fb7-a0f1d1eea360', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Teaching (cognition)', 'On one account, adults signal that a demonstration is meant to teach, using eye contact and infant-directed speech. Infants are tuned to these signals and then treat what is shown as general knowledge.', 'b0040254-6692-5ff3-8c4a-41b7a0bd1e51', '{"level":"discipline-facet","facet_of":"Teaching","definition":"On one account, adults signal that a demonstration is meant to teach, using eye contact and infant-directed speech. Infants are tuned to these signals and then treat what is shown as general knowledge.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-teaching-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('3e33244c-f4e1-5107-87c0-56f8cf8e1718', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Teaching (education)', 'A teacher plans tasks, explains, checks understanding and adjusts to the class. Intention and a stated learning goal are present. Success is judged by what students can do later.', 'b0040254-6692-5ff3-8c4a-41b7a0bd1e51', '{"level":"discipline-facet","facet_of":"Teaching","definition":"A teacher plans tasks, explains, checks understanding and adjusts to the class. Intention and a stated learning goal are present. Success is judged by what students can do later.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-teaching-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ac8e51ce-0b6f-59d1-9518-6127a3d49747', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Teaching (AI and computation)', 'Technical reading: tutoring software picks tasks, hints and feedback from a student''s answers by rules or learned patterns. People designed it to fill a teaching role. The software has no intent that the student understand.', 'b0040254-6692-5ff3-8c4a-41b7a0bd1e51', '{"level":"discipline-facet","facet_of":"Teaching","definition":"Technical reading: tutoring software picks tasks, hints and feedback from a student''s answers by rules or learned patterns. People designed it to fill a teaching role. The software has no intent that the student understand.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-teaching-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Metacognition
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"A thinker''s monitoring and control of its own thinking: judging how well it knows or understands something, noticing when a strategy fails and switching to another.","excludes":"Knowing facts about thinking differs from controlling thinking in the moment. Confidence is not accuracy. Declining a hard trial may reflect monitoring and may show no awareness. A machine''s confidence score is a computed number and shows no awareness of its own thinking.","core_counterparts":[],"curriculum_use":"No digest case tags it. Typical use is school goals about reviewing one''s own work and strategies, and the OpenEvo content anchor Our Mind.","grounding":["ConceptBase OE-SANDBOX-CONCEPT-000011 (sandbox tier)","ConceptBase OE-CONCEPT-openevo-design-concept-our-mind","DOI 10.1037/0003-066X.34.10.906 (Flavell 1979, Crossref verified)","DOI 10.1017/S0140525X03000086 (Smith, Shields and Washburn 2003, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '575e2873-964e-56c1-88ef-8908791c8f92';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('77c038dc-7233-596c-b5b4-fb7067c9cf26', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Metacognition (cognition)', 'People judge how well they know something, how hard a task is and whether to keep going. These judgments guide study and problem solving. They can be miscalibrated, with too much or too little confidence. Young children show early forms.', '575e2873-964e-56c1-88ef-8908791c8f92', '{"level":"discipline-facet","facet_of":"Metacognition","definition":"People judge how well they know something, how hard a task is and whether to keep going. These judgments guide study and problem solving. They can be miscalibrated, with too much or too little confidence. Young children show early forms.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-metacognition-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9baa7812-0657-59b7-8a3e-20691592f637', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Metacognition (education)', 'Learners plan, check and revise their own work. Teachers prompt this with questions such as ''How do I know I understand?'' and model it aloud. It is often taught as a strategy meant to apply across subjects.', '575e2873-964e-56c1-88ef-8908791c8f92', '{"level":"discipline-facet","facet_of":"Metacognition","definition":"Learners plan, check and revise their own work. Teachers prompt this with questions such as ''How do I know I understand?'' and model it aloud. It is often taught as a strategy meant to apply across subjects.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-metacognition-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('56806b5c-56ab-562a-9ec1-d4d8731a5fd1', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Metacognition (biology)', 'Comparative studies test whether monkeys, apes and a few other animals decline difficult trials, which may reflect tracking their own uncertainty. Simpler explanations, such as learned cues, are also proposed. Whether any awareness is involved is debated.', '575e2873-964e-56c1-88ef-8908791c8f92', '{"level":"discipline-facet","facet_of":"Metacognition","definition":"Comparative studies test whether monkeys, apes and a few other animals decline difficult trials, which may reflect tracking their own uncertainty. Simpler explanations, such as learned cues, are also proposed. Whether any awareness is involved is debated.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-metacognition-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Theory of Mind
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Representing another agent''s goals, beliefs or knowledge, and using that to interpret and predict what it will do. The represented states can differ from the facts and from one''s own.","excludes":"Mental-state attributions can be wrong, and the attributed state can differ from the facts. Predicting an agent''s behavior does not show that the predictor feels, understands or wants anything. Passing or failing one test, in children, animals or language models, may not carry over to other tasks.","core_counterparts":[],"curriculum_use":"No digest case tags it. Typical use is child development, comparing animal and human social thinking, and perspective-taking topics such as understanding others in Ethik grade 6.","grounding":["ConceptBase OE-SANDBOX-CONCEPT-000010 (sandbox tier)","DOI 10.1017/S0140525X00076512 (Premack and Woodruff 1978, Crossref verified)","DOI 10.1111/1467-8624.00304 (Wellman, Cross and Watson 2001, Crossref verified)","DOI 10.1016/j.tics.2008.02.010 (Call and Tomasello 2008, Crossref verified)","DOI 10.1126/science.aaf8110 (Krupenye et al. 2016, Crossref verified)","DOI 10.2307/2025382 (Dennett 1971, Crossref verified)","DOI 10.18653/v1/2020.acl-main.463 (Bender and Koller 2020, Crossref verified)","DOI 10.1038/s41562-024-01882-z (Strachan et al. 2024, Crossref verified; tests of language models and humans on theory-of-mind tasks)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = 'e6f78871-2017-55c6-8739-9a9c3a249315';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('115f7c78-5903-5d85-acae-317e09245fb5', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Theory of Mind (cognition)', 'Children come to predict actions from what another person believes, including false beliefs, at about four to five years in standard tasks. Earlier forms track goals and attention.', 'e6f78871-2017-55c6-8739-9a9c3a249315', '{"level":"discipline-facet","facet_of":"Theory of Mind","definition":"Children come to predict actions from what another person believes, including false beliefs, at about four to five years in standard tasks. Earlier forms track goals and attention.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-theory-of-mind-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c9c17405-140c-5edf-be7e-8ae2033fb4b7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Theory of Mind (biology)', 'Studies ask whether apes and other animals anticipate actions from what another sees, wants or believes. Evidence is stronger for goals and perception than for false belief, and the question remains debated.', 'e6f78871-2017-55c6-8739-9a9c3a249315', '{"level":"discipline-facet","facet_of":"Theory of Mind","definition":"Studies ask whether apes and other animals anticipate actions from what another sees, wants or believes. Evidence is stronger for goals and perception than for false belief, and the question remains debated.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-theory-of-mind-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1cadfcb9-27c3-50e8-b131-a61c704cdc9b', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Theory of Mind (AI and computation)', 'Technical reading: agent-modeling programs estimate another agent''s goals from its behavior to predict its next move. Language models are tested on false-belief stories. Passing such tests shows how their text output behaves and settles nothing about inner states.', 'e6f78871-2017-55c6-8739-9a9c3a249315', '{"level":"discipline-facet","facet_of":"Theory of Mind","definition":"Technical reading: agent-modeling programs estimate another agent''s goals from its behavior to predict its next move. Language models are tested on false-belief stories. Passing such tests shows how their text output behaves and settles nothing about inner states.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-theory-of-mind-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Intuitive Theories
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Informal, domain-specific explanations of how things work, such as folk physics, folk biology and folk psychology, formed before and outside instruction.","excludes":"Intuitive theories are often useful and need not be wrong. Intuitive means formed without instruction and does not mean innate. They differ from formal models, which are stated openly and tested. Purpose-based explanations are common and do not show a learner is careless.","core_counterparts":[],"curriculum_use":"No digest case tags it. Typical use is teaching that starts from student preconceptions, such as purpose-based explanations of traits in evolution lessons.","grounding":["ConceptBase OE-SANDBOX-CONCEPT-000012 (sandbox tier)","TheoryBase OE-MISCONCEPTION-need-based-teleology","TheoryBase OE-PROPOSITION-agential-biases-as-barriers","DOI 10.1037/a0028044 (Gopnik and Wellman 2012, Crossref verified)","DOI 10.1111/j.1468-0017.1992.tb00202.x (Gopnik and Wellman 1992, Crossref verified)","DOI 10.1146/annurev-anthro-081309-145822 (Gelman and Legare 2011, Crossref verified)","DOI 10.1016/S0010-0277(99)00010-4 (Kelemen 1999, Crossref verified)","DOI 10.1016/j.cognition.2012.04.005 (Shtulman and Valcarcel 2012, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = 'ce917c30-aaf6-59a9-b20a-36ecebf5b68f';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('a0c591c8-b017-53cb-9df0-1d07d06359e5', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Intuitive Theories (cognition)', 'Young children expect objects to fall, living things to grow from inside and people to act on wants. These expectations support explanation and prediction, and they change with age and evidence.', 'ce917c30-aaf6-59a9-b20a-36ecebf5b68f', '{"level":"discipline-facet","facet_of":"Intuitive Theories","definition":"Young children expect objects to fall, living things to grow from inside and people to act on wants. These expectations support explanation and prediction, and they change with age and evidence.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-intuitive-theories-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1054e6a8-38fc-568e-9f9a-e1436773225d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Intuitive Theories (education)', 'Students arrive with ideas such as ''organisms change because they need to''. Instruction can build on them, revise them or compete with them, and they often resurface under time pressure even after the science is learned.', 'ce917c30-aaf6-59a9-b20a-36ecebf5b68f', '{"level":"discipline-facet","facet_of":"Intuitive Theories","definition":"Students arrive with ideas such as ''organisms change because they need to''. Instruction can build on them, revise them or compete with them, and they often resurface under time pressure even after the science is learned.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-intuitive-theories-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c9579496-b0d2-5bca-8aba-0b250482293d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Intuitive Theories (culture)', 'Communities share folk theories, for example about illness or inheritance, and pass them on through talk and practice. Content differs across cultures, while some early expectations recur widely.', 'ce917c30-aaf6-59a9-b20a-36ecebf5b68f', '{"level":"discipline-facet","facet_of":"Intuitive Theories","definition":"Communities share folk theories, for example about illness or inheritance, and pass them on through talk and practice. Content differs across cultures, while some early expectations recur widely.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-intuitive-theories-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Analogical Reasoning
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Using a familiar case to understand a new one by matching the relations between their parts, then checking which matches hold and where the match breaks.","excludes":"Analogy needs matching relations, and surface resemblance alone does not count. Every analogy breaks somewhere. A mapping proposes a hypothesis and needs separate evidence. A program that scores a match is not reasoning as a person does. Cross-domain analogies, such as selection in biology and culture, need stated break points.","core_counterparts":[],"curriculum_use":"Describes analogy-based teaching, such as breeders'' selection as a way into natural selection. No Sachsen digest case tags it directly.","grounding":["ConceptBase OE-SANDBOX-CONCEPT-000013 (sandbox tier)","DOI 10.1207/s15516709cog0702_3 (Gentner 1983, Crossref verified)","DOI 10.1016/0004-3702(89)90077-5 (Falkenhainer, Forbus and Gentner 1989, Crossref verified)","DOI 10.1016/j.tics.2021.03.002 (Brand, Mesoudi and Smaldino 2021, Crossref verified)","DOI 10.1111/tops.12703 (Bramley et al. 2023, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '7c75aef6-b615-572a-aa01-b2c82591cd2f';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('007a0bcc-6149-51d5-ad74-bd12a6558796', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Analogical Reasoning (cognition)', 'A reasoner recalls a familiar case, maps its relational structure onto the new case and carries over inferences. Matching on shared relations gives better analogies than matching on appearance.', '7c75aef6-b615-572a-aa01-b2c82591cd2f', '{"level":"discipline-facet","facet_of":"Analogical Reasoning","definition":"A reasoner recalls a familiar case, maps its relational structure onto the new case and carries over inferences. Matching on shared relations gives better analogies than matching on appearance.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-analogical-reasoning-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('550863e3-d474-51af-aef6-eda3bf5424c8', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Analogical Reasoning (education)', 'Teachers and students build analogies and check where they fail, for example comparing breeders'' choices with natural selection. Listing what maps and what breaks guards against false carry-over.', '7c75aef6-b615-572a-aa01-b2c82591cd2f', '{"level":"discipline-facet","facet_of":"Analogical Reasoning","definition":"Teachers and students build analogies and check where they fail, for example comparing breeders'' choices with natural selection. Listing what maps and what breaks guards against false carry-over.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-analogical-reasoning-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e642de4c-ed98-5df0-8171-3863b764dc66', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Analogical Reasoning (culture)', 'One proposal holds that analogies help complex ideas pass between people with less distortion, which supports cumulative cultural change. Scientists also move ideas between fields by analogy.', '7c75aef6-b615-572a-aa01-b2c82591cd2f', '{"level":"discipline-facet","facet_of":"Analogical Reasoning","definition":"One proposal holds that analogies help complex ideas pass between people with less distortion, which supports cumulative cultural change. Scientists also move ideas between fields by analogy.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-analogical-reasoning-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d59fb20a-b16e-5cb3-acce-dd28eee5135c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Analogical Reasoning (AI and computation)', 'Technical reading: programs such as the structure-mapping engine match relational descriptions of a known case and a new case and score the match. People write the descriptions. The program follows a stated procedure and claims no insight.', '7c75aef6-b615-572a-aa01-b2c82591cd2f', '{"level":"discipline-facet","facet_of":"Analogical Reasoning","definition":"Technical reading: programs such as the structure-mapping engine match relational descriptions of a known case and a new case and score the match. People write the descriptions. The program follows a stated procedure and claims no insight.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-analogical-reasoning-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Distributed Cognition
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Thinking or remembering carried out by a system of several people and tools, so that the whole system does the task and no single member holds all of it.","excludes":"A tool in the system stores and transforms information but holds no goals of its own. A network of computers is a distributed system and counts here only when it serves a human thinking task. Groups can also think worse than their best member.","core_counterparts":[{"space":"comp","label":"Distributed System","relation":"related"}],"curriculum_use":"Describes personal memory aids in Sachunterricht grades 1 and 2, media and databases used as outside memory, and teamwork on shared tasks. No digest case tags it directly.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-distributed-cognition","DOI 10.1207/s15516709cog1903_1 (Hutchins 1995, Crossref verified)","DOI 10.1145/353485.353487 (Hollan, Hutchins and Kirsh 2000, Crossref verified)","DOI 10.1093/analys/58.1.7 (Clark and Chalmers 1998, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = 'b889941f-8b31-56a6-aef3-e3e9f26f79ca';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6992fc88-cdaa-593b-84c9-5cfc5299a638', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Distributed Cognition (cognition)', 'In an airliner cockpit, the pilots, a speed card, the markers on the speed dial and their talk together set and remember the speeds needed for landing. Each holds a part. The unit of study is the whole cockpit system.', 'b889941f-8b31-56a6-aef3-e3e9f26f79ca', '{"level":"discipline-facet","facet_of":"Distributed Cognition","definition":"In an airliner cockpit, the pilots, a speed card, the markers on the speed dial and their talk together set and remember the speeds needed for landing. Each holds a part. The unit of study is the whole cockpit system.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-distributed-cognition-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('194fe3d9-6475-596c-a445-41e14fff7323', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Distributed Cognition (technology)', 'Notes, calculators, maps, search tools and AI assistants hold part of a person''s task, and their design shapes how the person thinks. The tool stores and transforms information for a goal the person holds.', 'b889941f-8b31-56a6-aef3-e3e9f26f79ca', '{"level":"discipline-facet","facet_of":"Distributed Cognition","definition":"Notes, calculators, maps, search tools and AI assistants hold part of a person''s task, and their design shapes how the person thinks. The tool stores and transforms information for a goal the person holds.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-distributed-cognition-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('783b2032-a7a3-56e4-a044-4f5ad364a9c9', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Distributed Cognition (culture)', 'Teams, institutions and written records let a community remember and decide beyond any member''s capacity, and they pass tasks on to newcomers.', 'b889941f-8b31-56a6-aef3-e3e9f26f79ca', '{"level":"discipline-facet","facet_of":"Distributed Cognition","definition":"Teams, institutions and written records let a community remember and decide beyond any member''s capacity, and they pass tasks on to newcomers.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-distributed-cognition-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Extended concept: Technology
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', '{"proposed_on":"2026-10-25","general":"Tools, techniques and systems that individuals or groups make or adopt to extend what they can do. Designs can be passed on, improved and combined over time.","excludes":"Technology has purposes set by makers and users. An artifact holds none of its own. Animal tool use may lack planning and accumulation. Technology is not always digital or new. A tool can extend one capacity and weaken another.","core_counterparts":[{"space":"comp","label":"Program","relation":"broader"},{"space":"comp","label":"Specification","relation":"related"},{"space":"comp","label":"Distributed System","relation":"broader"}],"curriculum_use":"Describes Technik und Computer grades 5 and 6 (designing, making and evaluating objects, work plans), tool use in human origins (biology grade 10) and industrialisation (history grade 8).","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-technology","ConceptBase OE-SANDBOX-CONCEPT-000005 (Machine Culture, sandbox tier)","DOI 10.1098/rspb.2002.2302 (Hunt and Gray 2003, Crossref verified)","DOI 10.1038/s41562-023-01742-2 (Brinkmann et al. 2023, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb) WHERE id = '1d89ba05-d574-53ea-aaa9-c513d9125e96';
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('3d36e9c0-b1f6-567e-b112-ae7688e788ef', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Technology (technology)', 'Engineers and makers design a tool or system to meet stated needs, build it, test it and revise it. Tests compare the result with the needs, and trade-offs are named.', '1d89ba05-d574-53ea-aaa9-c513d9125e96', '{"level":"discipline-facet","facet_of":"Technology","definition":"Engineers and makers design a tool or system to meet stated needs, build it, test it and revise it. Tests compare the result with the needs, and trade-offs are named.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-technology-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('81df97a9-97dc-585d-9c5a-2fb5d5ce2cf1', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Technology (culture)', 'Technologies are shared practices as well as objects: skills, materials and know-how pass on by teaching and imitation, and improvements accumulate across generations and shape how groups live and work.', '1d89ba05-d574-53ea-aaa9-c513d9125e96', '{"level":"discipline-facet","facet_of":"Technology","definition":"Technologies are shared practices as well as objects: skills, materials and know-how pass on by teaching and imitation, and improvements accumulate across generations and shape how groups live and work.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-technology-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8a428fc1-3e68-50ea-b1ab-cc0de8b9ab73', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Technology (biology)', 'Some animals make and use tools, such as New Caledonian crows shaping hooks from twigs. Designs differ between groups and may be learned from others. Whether improvements accumulate is debated.', '1d89ba05-d574-53ea-aaa9-c513d9125e96', '{"level":"discipline-facet","facet_of":"Technology","definition":"Some animals make and use tools, such as New Caledonian crows shaping hooks from twigs. Designs differ between groups and may be learned from others. Whether improvements accumulate is debated.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-technology-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('46fb956f-eb8d-59b5-8dcd-f8e1b6c22b67', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Technology (education)', 'As a school subject, technology is designing, making and evaluating objects. It also covers digital tools for learning. Students judge a design by whether it meets its requirements.', '1d89ba05-d574-53ea-aaa9-c513d9125e96', '{"level":"discipline-facet","facet_of":"Technology","definition":"As a school subject, technology is designing, making and evaluating objects. It also covers digital tools for learning. Students judge a design by whether it meets its requirements.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-technology-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('218782b6-5070-5ab3-8fe7-d4fa32dbbe8f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Technology (AI and computation)', 'Technical reading: AI systems are tools that process data to give outputs for users who set the goals. The system has no purpose of its own.', '1d89ba05-d574-53ea-aaa9-c513d9125e96', '{"level":"discipline-facet","facet_of":"Technology","definition":"Technical reading: AI systems are tools that process data to give outputs for users who set the goals. The system has no purpose of its own.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-technology-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Abstraction
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('cb98e497-14c8-58c1-b14d-0467b037a8da', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Abstraction', 'Leaving out detail so that what matters for some use stays in view. The leaving-out can be chosen, as in a map or a software layer, or happen without choice, as when a concept forms from many instances.', '938e144b-1e6a-5027-8292-f19fc111d640', '{"definition":"Leaving out detail so that what matters for some use stays in view. The leaving-out can be chosen, as in a map or a software layer, or happen without choice, as when a concept forms from many instances.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-abstraction","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"What is left out suits one use and may matter for another. Everyday ''abstract'' often means vague or hard to picture; abstraction here is exact about what it keeps. In concept formation it is often unconscious. In computing it is a deliberate design choice.","core_counterparts":[{"space":"comp","label":"Abstraction","relation":"broader"},{"space":"comp","label":"Model","relation":"related"}],"curriculum_use":"Describes the geography topic on the map as a generalized picture of reality (grade 5), simplified models in several subjects, and layers and interfaces in informatics. All four digest cases fit the narrow sense.","grounding":["ConceptBase OE-COMPETENCY-000281 (AI4K12: Representation (Abstraction))","ConceptBase OE-COMPETENCY-000284 (AI4K12 3-5: different maps capture different aspects)","ConceptBase OE-COMPETENCY-000286 (AI4K12 6-8: a game board described in plain language)","DOI 10.1145/1118178.1118215 (Wing 2006, Crossref verified)","DOI 10.1098/rsta.2008.0118 (Wing 2008, Crossref verified)","DOI 10.1207/s15516709cog0702_3 (Gentner 1983, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9b2ae7d4-888f-52c6-836c-7f20459c0385', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Abstraction (cognition)', 'Forming a concept or schema by dropping differences among instances, as ''bird'' from many birds. The abstract relational structure of a case is what an analogy carries to another case.', 'cb98e497-14c8-58c1-b14d-0467b037a8da', '{"level":"discipline-facet","facet_of":"Abstraction","definition":"Forming a concept or schema by dropping differences among instances, as ''bird'' from many birds. The abstract relational structure of a case is what an analogy carries to another case.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-abstraction-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('cd1207a9-5623-53fe-8847-8d2c321c280b', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Abstraction (culture)', 'Maps, diagrams and summaries leave out detail on purpose. Mapmakers generalize coastlines and roads so the picture serves one use, and a different use needs different detail.', 'cb98e497-14c8-58c1-b14d-0467b037a8da', '{"level":"discipline-facet","facet_of":"Abstraction","definition":"Maps, diagrams and summaries leave out detail on purpose. Mapmakers generalize coastlines and roads so the picture serves one use, and a different use needs different detail.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-abstraction-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('df55cbce-b5e0-5c66-8277-20cd0595d66e', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Abstraction (education)', 'Students move from drawing a map of their school to asking what each kind of map keeps and leaves out, and later to describing a game board or a concept by its essential parts.', 'cb98e497-14c8-58c1-b14d-0467b037a8da', '{"level":"discipline-facet","facet_of":"Abstraction","definition":"Students move from drawing a map of their school to asking what each kind of map keeps and leaves out, and later to describing a game board or a concept by its essential parts.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-abstraction-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('fc867f49-00af-5334-b5bd-4400335ddade', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Abstraction (AI and computation)', 'Hiding how something works behind an interface, so that users and other parts need only know what it does. Layers each hide the one below, and the chosen level of detail is a design decision.', 'cb98e497-14c8-58c1-b14d-0467b037a8da', '{"level":"discipline-facet","facet_of":"Abstraction","definition":"Hiding how something works behind an interface, so that users and other parts need only know what it does. Layers each hide the one below, and the chosen level of detail is a design decision.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-abstraction-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Algorithm
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6100cc68-c0eb-5f67-823e-5f5c4c200b9f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Algorithm', 'A fixed series of steps that a person or machine can follow to get from a given start to a result.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"definition":"A fixed series of steps that a person or machine can follow to get from a given start to a result.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-algorithm","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"A strict algorithm has finite, exact steps and needs no judgment, and many recipes and work plans fail that test. A natural process described as an algorithm has no author and no list of steps. A procedure that runs is not shown to be correct or fast.","core_counterparts":[{"space":"comp","label":"Algorithm","relation":"broader"},{"space":"comp","label":"Program","relation":"related"}],"curriculum_use":"Describes informatics grade 7 and 8 algorithm topics including transfer to everyday cases, dichotomous keys in biology grades 6 and 9, and the work plan in Technik und Computer grades 5 and 6.","grounding":["ConceptBase OE-COMPETENCY-000321 (AI4K12 3-5: an algorithm chooses the next move)","DOI 10.1038/msb.2011.78 (Navlakha and Bar-Joseph 2011, Crossref verified)","DOI 10.1145/1118178.1118215 (Wing 2006, Crossref verified)"],"confidence":"low","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('740a0382-f93b-5116-82ff-2d98c9c0f130', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Algorithm (AI and computation)', 'Finite, unambiguous steps a machine can execute with no judgment, turning input into output. A program is an algorithm written in a language the machine can run. Correctness and step counts can be checked.', '6100cc68-c0eb-5f67-823e-5f5c4c200b9f', '{"level":"discipline-facet","facet_of":"Algorithm","definition":"Finite, unambiguous steps a machine can execute with no judgment, turning input into output. A program is an algorithm written in a language the machine can run. Correctness and step counts can be checked.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-algorithm-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('71ee6595-1f1d-528a-a0b8-a787ae673dee', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Algorithm (education)', 'Step-by-step procedures taught in school, such as long division, a recipe or a key that asks one yes-or-no question per step to name a plant. Students test whether each step is clear enough that anyone could follow it without guessing.', '6100cc68-c0eb-5f67-823e-5f5c4c200b9f', '{"level":"discipline-facet","facet_of":"Algorithm","definition":"Step-by-step procedures taught in school, such as long division, a recipe or a key that asks one yes-or-no question per step to name a plant. Students test whether each step is clear enough that anyone could follow it without guessing.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-algorithm-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('629d3996-ecde-5d8f-8359-5795ff142946', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Algorithm (technology)', 'A work plan or production sequence lists operations in order with tools and materials. Workers may need judgment at a step, so it meets the strict test only if every step is exact.', '6100cc68-c0eb-5f67-823e-5f5c4c200b9f', '{"level":"discipline-facet","facet_of":"Algorithm","definition":"A work plan or production sequence lists operations in order with tools and materials. Workers may need judgment at a step, so it meets the strict test only if every step is exact.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-algorithm-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Feedback
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b8b2412c-6f27-54f8-b612-4c595d3e9059', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Feedback', 'Information about a system''s own output is returned to the system, so that its later behavior depends on its earlier results. The loop can damp a change or amplify it.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"definition":"Information about a system''s own output is returned to the system, so that its later behavior depends on its earlier results. The loop can damp a change or amplify it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-feedback","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"In everyday speech positive feedback means praise and negative feedback means criticism. In systems, negative feedback damps change and positive feedback amplifies it, whatever the tone. A comment the learner never uses is no loop. Late feedback can cause swings.","core_counterparts":[{"space":"comp","label":"Feedback","relation":"broader"}],"curriculum_use":"Describes the biological control loop for blood sugar (biology grade 8) and feedback to learners as used in lessons. The blood sugar case tags as narrower under Comp-Core.","grounding":["ConceptBase OE-COMPETENCY-000128 (NGSS HS-LS1-3: feedback mechanisms maintain homeostasis)","ConceptBase OE-COMPETENCY-000397 (AI4K12 3-5: a reinforcement signal lets a computer learn from experience)","DOI 10.1086/286788 (Rosenblueth, Wiener and Bigelow 1943, Crossref verified)","DOI 10.3102/003465430298487 (Hattie and Timperley 2007, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e72c9a48-7282-5e3f-bae7-f441d06acbad', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Feedback (biology)', 'Body systems hold conditions near a range with loops: receptors detect a change, a control center compares it with a set range and organs respond, as insulin lowers blood sugar after a meal.', 'b8b2412c-6f27-54f8-b612-4c595d3e9059', '{"level":"discipline-facet","facet_of":"Feedback","definition":"Body systems hold conditions near a range with loops: receptors detect a change, a control center compares it with a set range and organs respond, as insulin lowers blood sugar after a meal.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-feedback-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('27ffa660-7a84-5a71-85bc-7366382c8daf', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Feedback (technology)', 'A controller compares a measured output with a target and adjusts the input, as a thermostat does. Designers choose the target, the sensor and the size of the correction.', 'b8b2412c-6f27-54f8-b612-4c595d3e9059', '{"level":"discipline-facet","facet_of":"Feedback","definition":"A controller compares a measured output with a target and adjusts the input, as a thermostat does. Designers choose the target, the sensor and the size of the correction.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-feedback-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ea31f1bc-57b5-57d3-8c08-a5a98b665051', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Feedback (education)', 'Information about a learner''s work, goal and gap that the learner uses to improve the next attempt. A grade or comment becomes feedback only when the learner acts on it.', 'b8b2412c-6f27-54f8-b612-4c595d3e9059', '{"level":"discipline-facet","facet_of":"Feedback","definition":"Information about a learner''s work, goal and gap that the learner uses to improve the next attempt. A grade or comment becomes feedback only when the learner acts on it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-feedback-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('60fca9e3-84ea-5292-a439-f014b3d9c4de', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Feedback (AI and computation)', 'Training loops compare a model''s output with a target or reward and adjust its numbers. Deployed systems can also feed their outputs back into the data they later learn from, which can amplify errors.', 'b8b2412c-6f27-54f8-b612-4c595d3e9059', '{"level":"discipline-facet","facet_of":"Feedback","definition":"Training loops compare a model''s output with a target or reward and adjust its numbers. Deployed systems can also feed their outputs back into the data they later learn from, which can amplify errors.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-feedback-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Model
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4507e96a-c6ac-5bcd-a258-1b83d33dbda3', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Model', 'A simplified stand-in for a system, built for a purpose, that people use to explain, predict or explore the system. It is judged by its fit to that purpose and can be revised.', '938e144b-1e6a-5027-8292-f19fc111d640', '{"definition":"A simplified stand-in for a system, built for a purpose, that people use to explain, predict or explore the system. It is judged by its fit to that purpose and can be revised.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-model","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"A model is not the system, and one built for a purpose may fail for another. A role model is an example to copy, a different sense of the word. Scientific models face tests against evidence. Ethics lessons also call worldviews and accounts of conscience models, judged by other standards.","core_counterparts":[{"space":"comp","label":"Model","relation":"broader"}],"curriculum_use":"Covers the hominid family tree, sector and city-region models, conscience models, the input-process-output model and scale models. Worldview ''models'' in the Ethik grade 10 topic count only if testable; an expert should judge.","grounding":["ConceptBase OE-CONCEPT-openevo-design-concept-computer-models","ConceptBase OE-COMPETENCY-000102 (NGSS MS-LS1-2: develop and use a model)","TheoryBase OE-THEORY-computational-models-as-theory-mediators","DOI 10.1002/tea.3660280907 (Grosslight et al. 1991, Crossref verified)","DOI 10.1080/095006900416884 (Harrison and Treagust 2000, Crossref verified)","DOI 10.1002/tea.20311 (Schwarz et al. 2009, Crossref verified)","unverified: mental models (Craik 1943; Johnson-Laird 1983) cited from memory"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Simulation","core_counterparts":[{"space":"comp","label":"Simulation","relation":"related"}],"reason":"A simulation is a model being run, so it shares the structure of Model. No Sachsen case in the digest separates the two. A facet of Model covers it.","confidence":"medium"}]}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('5d7258b5-2255-57f9-914f-2fc45f5000bb', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Model (education)', 'School models include scale models, diagrams, analogies, equations and simulations. Students use them to explain a phenomenon, learn that a model leaves features out, and test and improve it, for example by changing a simulation''s settings.', '4507e96a-c6ac-5bcd-a258-1b83d33dbda3', '{"level":"discipline-facet","facet_of":"Model","definition":"School models include scale models, diagrams, analogies, equations and simulations. Students use them to explain a phenomenon, learn that a model leaves features out, and test and improve it, for example by changing a simulation''s settings.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-model-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8a47b628-8e01-5bdb-8308-c9630686b03a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Model (biology)', 'Biologists use diagrams, equations and trees as models. A tree of human ancestors states which lineages share ancestors, and new fossils or DNA can revise it.', '4507e96a-c6ac-5bcd-a258-1b83d33dbda3', '{"level":"discipline-facet","facet_of":"Model","definition":"Biologists use diagrams, equations and trees as models. A tree of human ancestors states which lineages share ancestors, and new fossils or DNA can revise it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-model-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('64bfb89e-3054-507e-af8b-3af1ab3e51d3', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Model (culture)', 'Geographers and economists use models such as the sector model of an economy or a model of a North American city region. They sort cases into types and state how parts relate. Places in the world differ from the model.', '4507e96a-c6ac-5bcd-a258-1b83d33dbda3', '{"level":"discipline-facet","facet_of":"Model","definition":"Geographers and economists use models such as the sector model of an economy or a model of a North American city region. They sort cases into types and state how parts relate. Places in the world differ from the model.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-model-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b129a886-cdd8-5c8d-8b95-551880b2fb4a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Model (cognition)', 'On one account, a mental model is a person''s internal, simplified stand-in used to reason about how something works. It can be incomplete or wrong, and it may run as a mental simulation.', '4507e96a-c6ac-5bcd-a258-1b83d33dbda3', '{"level":"discipline-facet","facet_of":"Model","definition":"On one account, a mental model is a person''s internal, simplified stand-in used to reason about how something works. It can be incomplete or wrong, and it may run as a mental simulation.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-model-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('28e15a13-8bda-5e5b-871c-294696fff17a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Model (AI and computation)', 'A formal description a computer can run: rules, equations or a fitted function whose numbers were set from data. Running it forward (a simulation) shows what follows; changing settings and rerunning shows what results depend on.', '4507e96a-c6ac-5bcd-a258-1b83d33dbda3', '{"level":"discipline-facet","facet_of":"Model","definition":"A formal description a computer can run: rules, equations or a fitted function whose numbers were set from data. Running it forward (a simulation) shows what follows; changing settings and rerunning shows what results depend on.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-model-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- New concept: Search
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c7c91feb-25f2-5996-aa6e-ddaa87585741', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Search', 'Looking through a set of possible options for one that meets a goal, by trying some and checking each against a criterion.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"definition":"Looking through a set of possible options for one that meets a goal, by trying some and checking each against a criterion.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-search","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","excludes":"Search needs a goal and a way to check candidates. Natural selection has no goal, so calling it a search covers only the trying and keeping. Searching for meaning is a figure of speech with no candidate set. Search may stop at good enough, and the criterion can shift.","core_counterparts":[{"space":"comp","label":"Search","relation":"broader"},{"space":"bio","label":"Natural Selection","relation":"related"}],"curriculum_use":"Describes the informatics grade 8 topic on search strategies and ranking of results, search strategies in Sachunterricht and Technik und Computer, and animal foraging. Leaves out ''Sinnsuche'' in Ethik grade 8.","grounding":["ConceptBase OE-CONCEPT-oe-interdisciplinary-selection (its AI sense is close to Search)","ConceptBase OE-COMPETENCY-000325 (AI4K12 9-12: problems as search from a start state to a goal state)","DOI 10.1145/360018.360022 (Newell and Simon 1976, Crossref verified)","DOI 10.1111/tops.12703 (Bramley et al. 2023, Crossref verified)","DOI 10.1086/409852 (Pyke, Pulliam and Charnov 1977, Crossref verified)"],"confidence":"medium","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('62eaf0c0-426b-537f-9876-c64a6a71e24e', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Search (AI and computation)', 'A program explores candidate states or answers and keeps those scoring higher on a stated objective. Web search ranks documents by a relevance score. Good-enough answers are often accepted when the best would take too long.', 'c7c91feb-25f2-5996-aa6e-ddaa87585741', '{"level":"discipline-facet","facet_of":"Search","definition":"A program explores candidate states or answers and keeps those scoring higher on a stated objective. Web search ranks documents by a relevance score. Good-enough answers are often accepted when the best would take too long.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-search-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('a9c18488-d3a8-5a37-9184-5bc44ef22307', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Search (cognition)', 'Problem solving as moving through possible steps toward a goal, trying options and testing them. People prune the options with rules of thumb. Local search from a familiar starting point is one proposed pattern.', 'c7c91feb-25f2-5996-aa6e-ddaa87585741', '{"level":"discipline-facet","facet_of":"Search","definition":"Problem solving as moving through possible steps toward a goal, trying options and testing them. People prune the options with rules of thumb. Local search from a familiar starting point is one proposed pattern.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-search-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4e44b48a-3f0b-5664-a2fe-fbea96a2b096', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Search (biology)', 'Animals search for food, mates or shelter by sampling places and moving on or staying according to what they find. Foraging theory asks which choices of where and how long to search raise food intake in a habitat.', 'c7c91feb-25f2-5996-aa6e-ddaa87585741', '{"level":"discipline-facet","facet_of":"Search","definition":"Animals search for food, mates or shelter by sampling places and moving on or staying according to what they find. Foraging theory asks which choices of where and how long to search raise food intake in a habitat.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-search-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2877973f-dc14-54be-b3a1-2dd00a26aa19', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Search (education)', 'Learners research a question by choosing search terms, scanning results and judging sources against the question. The criterion is the learner''s need, which can change as they learn.', 'c7c91feb-25f2-5996-aa6e-ddaa87585741', '{"level":"discipline-facet","facet_of":"Search","definition":"Learners research a question by choosing search terms, scanning results and judging sources against the question. The criterion is the learner''s need, which can change as they learn.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-search-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-25","grounding":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- Core concepts handled as domain meanings of Selection
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('proposed_extension', coalesce(metadata->'proposed_extension', '{}'::jsonb) || '{"proposed_on":"2026-10-25","draft_note":"AI-drafted on 2026-10-25 from the Core vocabularies, the concept crosswalk and the Sachsen tagging evidence. No subject-matter expert has reviewed it.","folded_core_concepts":[{"core_concept":"Differential Reproduction","core_counterparts":[{"space":"bio","label":"Natural Selection","relation":"broader"},{"space":"bio","label":"Differential Reproduction","relation":"broader"}],"reason":"Same idea as the biology sense of Selection: variants leave different numbers of offspring. The facets restate it as copies left, which also fits culture and computing.","confidence":"medium"},{"core_concept":"Sexual Selection","core_counterparts":[{"space":"bio","label":"Sexual Selection","relation":"broader"}],"reason":"A case of selection where other members of the species do the choosing or competing. It fits Selection. Other domains have no documented process of this kind, so only biology gets a facet.","confidence":"medium"}]}'::jsonb) WHERE id = '0573db35-8451-5189-998c-8619ea1d26ec';

-- Introduction: state the aim of the space
UPDATE projects SET introduction = introduction || '

How this space differs from the Core spaces. Bio-Core, Social-Core and Computational-Core each define their concepts inside one discipline. This space defines each concept in a general way that names what the domains share. It gives a separate meaning for each domain where a documented process or practice fits, and it says what does not carry over from one domain to another, for example whether intention is needed or whether copies exist. A concept that belongs to one discipline only, such as speciation, has no general entry. A meaning that begins with ''Technical reading'' describes how computing uses a word that normally describes a mind, and it makes no claim that software has one. The added concepts and domain meanings have the status proposed. AI drafted them, a second AI checked them and no subject expert has reviewed them.' WHERE id = '371fce26-d1f3-439b-95df-0a0e38b8a824' AND introduction NOT LIKE '%How this space differs from the Core spa%';

